void lv_assert_handler(void)
{
    /* The stock body is LV_ASSERT_HANDLER, which defaults to `while(1);`.
     * On this product that is a silent permanent freeze: the LVGL thread
     * spins inside lv_timer_handler() still holding lvgl_ui_lock(), so
     * every thread that queues LVGL work (agent reply path, pet state,
     * PTT) blocks forever and the console stops echoing too.  One failed
     * lv_malloc() therefore looks exactly like a dead board with no
     * message.  Make it loud and fatal instead: syslog the fact (the
     * expression itself already went out through the registered LVGL log
     * callback) and abort, which gives a NuttX panic dump. */
    syslog(LOG_ERR, "[lvgl] assertion failed -> abort()\n");
    abort();

    LV_UNREACHABLE();
}

