370: /**
371:  * Copy text into a fixed buffer with UTF-8-aware truncation.  Copies at most
372:  * dst_size-1 bytes, then if the cut lands inside a multi-byte UTF-8 sequence
373:  * (leading byte 0xC0..0xF4 not followed by enough continuation bytes 0x80..0xBF),
374:  * trims back to the last complete character.  Always NUL-terminates.
375:  *
376:  * This prevents a half-cut Chinese char from rendering as a replacement glyph
377:  * at the end of a truncated Agent reply.
378:  */
379: static void chat_view_copy_text(char* dst, const char* src, size_t dst_size)
380: {
381:     if (dst_size == 0) return;
382:     size_t n = strnlen(src, dst_size - 1);
383:     memcpy(dst, src, n);
384:     dst[n] = '\0';
385: 
386:     /* If we filled the buffer, the last char may be incomplete.  Walk back
387:      * from the end to find a UTF-8 leading byte and check its expected length
388:      * against the remaining bytes. */
389:     if (n < dst_size - 1) return;          /* src fit fully, no truncation */
390:     size_t i = n;
391:     while (i > 0) {
392:         unsigned char c = (unsigned char)dst[i - 1];
393:         if ((c & 0xC0) != 0x80) break;     /* not a continuation byte */
394:         i--;
395:     }
396:     if (i == 0) return;                     /* all continuation bytes? give up */
397:     unsigned char lead = (unsigned char)dst[i - 1];
398:     size_t need;
399:     if      ((lead & 0x80) == 0x00) need = 1;   /* ASCII */
400:     else if ((lead & 0xE0) == 0xC0) need = 2;
401:     else if ((lead & 0xF0) == 0xE0) need = 3;
402:     else if ((lead & 0xF8) == 0xF0) need = 4;
403:     else { dst[i - 1] = '\0'; return; }         /* invalid lead, cut it */
404:     if (n - (i - 1) < need) {
405:         dst[i - 1] = '\0';                      /* incomplete seq, trim it */
406:     }
407: }

