1527	/* Classify an Agent reply text into a coarse card category so the
1528	 * left color bar gives a glanceable cue.  Matching is intentionally
1529	 * simple (case-insensitive substring) — this is a visual hint, not
1530	 * a parser.  Returns the palette color for the matched category. */
1531	static uint32_t chat_view_classify_reply(const char* text)
1532	{
1533	    if (!text || !*text) {
1534	        return LVGL_UI_CARD_COLOR_PLAIN;
1535	    }
1536	
1537	    /* Build a lowercase copy (ASCII only; CJK passes through untouched)
1538	     * so substring checks are case-insensitive for the latin keywords. */
1539	    char buf[LVGL_UI_MSG_MAX_LEN];
1540	    size_t i;
1541	    for (i = 0; i < sizeof(buf) - 1 && text[i]; i++) {
1542	        buf[i] = (text[i] >= 'A' && text[i] <= 'Z') ? (text[i] + 32) : text[i];
1543	    }
1544	    buf[i] = '\0';
1545	
1546	    /* Conclusion: explicit yes/no or recommendation phrasing */
1547	    if (strstr(buf, "yes") || strstr(buf, " no") || strstr(buf, "no.") ||
1548	        strstr(buf, "no,") || strstr(buf, "\xe5\x80\xbc\xe5\xbe\x97") /* 值得 */ ||
1549	        strstr(buf, "\xe4\xb8\x8d\xe5\xbb\xba\xe8\xae\xae") /* 不建议 */ ||
1550	        strstr(buf, "\xe5\xbb\xba\xe8\xae\xae") /* 建议 */ ) {
1551	        return LVGL_UI_CARD_COLOR_CONCLUSION;
1552	    }
1553	
1554	    /* Structured: Gerrit change status keywords (latin) or 状态: */
1555	    if (strstr(buf, "merged") || strstr(buf, "abandoned") ||
1556	        strstr(buf, "status:") || strstr(buf, "\xe7\x8a\xb6\xe6\x80\x81") /* 状态 */ ) {
1557	        return LVGL_UI_CARD_COLOR_STRUCTURED;
1558	    }
1559	
1560	    /* Jira: workflow status or assignee fields */
1561	    if (strstr(buf, "more info") || strstr(buf, "assignee") ||
1562	        strstr(buf, "\xe7\xbb\x8f\xe5\x8a\x9e\xe4\xba\xba") /* 经办人 */ ||
1563	        strstr(buf, "jira") ) {
1564	        return LVGL_UI_CARD_COLOR_JIRA;
1565	    }
1566	
1567	    return LVGL_UI_CARD_COLOR_PLAIN;
1568	}
