231	 * Find the last item of a track
232	 */
233	static int32_t find_track_end(lv_obj_t * cont, flex_t * f, int32_t item_start_id, int32_t max_main_size,
234	                              int32_t item_gap, track_t * t)
235	{
236	    int32_t w_set = lv_obj_get_style_width(cont, LV_PART_MAIN);
237	    int32_t h_set = lv_obj_get_style_height(cont, LV_PART_MAIN);
238	
239	    /*Can't wrap if the size is auto (i.e. the size depends on the children)*/
240	    if(f->wrap && ((f->row && w_set == LV_SIZE_CONTENT) || (!f->row && h_set == LV_SIZE_CONTENT))) {
241	        f->wrap = false;
242	    }
243	    int32_t(*get_main_size)(const lv_obj_t *) = (f->row ? lv_obj_get_width_with_margin : lv_obj_get_height_with_margin);
244	    int32_t(*get_cross_size)(const lv_obj_t *) = (!f->row ? lv_obj_get_width_with_margin :
245	                                                  lv_obj_get_height_with_margin);
246	
247	    t->track_main_size = 0;
248	    t->track_fix_main_size = 0;
249	    t->grow_item_cnt = 0;
250	    t->track_cross_size = 0;
251	    t->item_cnt = 0;
252	    t->grow_dsc = NULL;
253	
254	    int32_t item_id = item_start_id;
255	
256	    lv_obj_t * item = lv_obj_get_child(cont, item_id);
257	    while(item) {
258	        if(item_id != item_start_id && lv_obj_has_flag(item, LV_OBJ_FLAG_FLEX_IN_NEW_TRACK)) break;
259	
260	        if(!lv_obj_has_flag_any(item, LV_OBJ_FLAG_IGNORE_LAYOUT | LV_OBJ_FLAG_HIDDEN | LV_OBJ_FLAG_FLOATING)) {
261	            uint8_t grow_value = lv_obj_get_style_flex_grow(item, LV_PART_MAIN);
262	            if(grow_value) {
263	                t->grow_item_cnt++;
264	                t->track_fix_main_size += item_gap;
265	                if(t->grow_dsc_calc) {
266	                    grow_dsc_t * new_dsc = lv_realloc(t->grow_dsc, sizeof(grow_dsc_t) * (t->grow_item_cnt));
267	                    LV_ASSERT_MALLOC(new_dsc);
268	                    if(new_dsc == NULL) return item_id;
269	
270	                    new_dsc[t->grow_item_cnt - 1].item = item;
271	                    new_dsc[t->grow_item_cnt - 1].min_size = f->row ? lv_obj_get_style_min_width(item, LV_PART_MAIN)
272	                                                             : lv_obj_get_style_min_height(item, LV_PART_MAIN);
273	                    new_dsc[t->grow_item_cnt - 1].max_size = f->row ? lv_obj_get_style_max_width(item, LV_PART_MAIN)
274	                                                             : lv_obj_get_style_max_height(item, LV_PART_MAIN);
275	                    new_dsc[t->grow_item_cnt - 1].grow_value = grow_value;
276	                    new_dsc[t->grow_item_cnt - 1].clamped = 0;
277	                    t->grow_dsc = new_dsc;
278	                }
279	            }
280	            else {
281	                int32_t item_size = get_main_size(item);
282	                if(f->wrap && t->track_fix_main_size + item_size > max_main_size) break;
283	                t->track_fix_main_size += item_size + item_gap;
284	            }
285	
286	            t->track_cross_size = LV_MAX(get_cross_size(item), t->track_cross_size);
287	            t->item_cnt++;
288	        }
289	
290	        item_id += f->rev ? -1 : +1;
291	        if(item_id < 0) break;
292	        item = lv_obj_get_child(cont, item_id);
293	    }
294	
295	    if(t->track_fix_main_size > 0) t->track_fix_main_size -= item_gap; /*There is no gap after the last item*/
296	
297	    /*If there is at least one "grow item" the track takes the full space*/
298	    t->track_main_size = t->grow_item_cnt ? max_main_size : t->track_fix_main_size;
299

