437	        uint32_t cur;
438	
439	        usleep(5000 * 1000);
440	        if (!s_lv_loop_running)
441	          {
442	            break;
443	          }
444	
445	        s_wd_ticks++;
446	
447	        cur = s_lv_frames;
448	        if (cur == last)
449	          {
450	            stall += 5;
451	          }
452	        else
