489	{
490	    struct sched_param sp;
491	    uint32_t frames = 0;
492	
493	    (void)arg;
494	
495	    /* LV_USE_LOG is on but LV_LOG_PRINTF is off, so every LVGL log line —
496	     * including "Asserted at expression: ... (Out of memory)" — was being
497	     * discarded.  Route them to syslog so an assert is visible before
498	     * lv_assert_handler() takes the system down. */
499	    lv_log_register_print_cb(lvgl_log_cb);
500	
501	    /* The loop thread was created with the default pthread priority
502	     * (inherited), so TLS / LLM dispatch / TTS work preempts it.  A frame
503	     * that is preempted mid-flush holds lvgl_ui_lock() for that whole
504	     * time, and every cross-thread LVGL caller (agent reply path, pet
505	     * state, PTT) blocks behind it.  Run at the UI priority instead. */
506	    sp.sched_priority = AGENT_LVGL_UI_PRIO;
507	    int prc = sched_setparam(0, &sp);
508	    syslog(LOG_INFO, "[%s] LVGL loop prio -> %d (rc=%d)\n",
509	           TAG, AGENT_LVGL_UI_PRIO, prc);
510	
511	    /* Stall detector — see ui_watchdog_thread().  Give it an explicit 8 KB
512	     * stack: CONFIG_PTHREAD_STACK_DEFAULT is 2048 here, which is marginal for
513	     * one snprintf, and the previous run's watchdog never printed a byte while
514	     * every other thread kept logging — a too-small stack is the likeliest
515	     * reason.  The creation result is logged so a silent watchdog can no
516	     * longer be confused with a wedged scheduler. */
517	    {
518	      pthread_attr_t wattr;
519	      int crc = -1;
520	
521	      if (pthread_attr_init(&wattr) == 0)
522	        {
523	          (void)pthread_attr_setstacksize(&wattr, 8192);
524	          crc = pthread_create(&s_lv_wd_tid, &wattr, ui_watchdog_thread, NULL);
525	          (void)pthread_attr_destroy(&wattr);
526	        }
527	
528	      syslog(LOG_INFO, "[%s] watchdog create rc=%d\n", TAG, crc);
529	    }

