65	int resp_buf_init(resp_buf_t* rb, size_t initial_cap)
66	{
67	    rb->data = calloc(1, initial_cap);
68	    if (!rb->data)
69	        return ERROR;
70	    rb->len = 0;
71	    rb->cap = initial_cap;
72	    return OK;
73	}
