305	/**
306	 * Return the model name to send in the API request.
307	 * Multi-provider gateways (e.g. OpenRouter) require the full
308	 * "provider/model" string, while single-vendor APIs expect only
309	 * the bare model name after the slash.
310	 */
311	const char* model_name_for_api(const char* model, const char* host)
312	{
313	    /* Multi-provider gateways need the full identifier */
314	    if (strstr(host, "openrouter.ai")) {
315	        return model;
316	    }
317	
318	    const char* slash = strchr(model, '/');
