321	
322	/* Direct path via vela_tls */
323	static int llm_http_direct(const char* post_data, resp_buf_t* rb,
324	    int* out_status)
325	{
326	    /* Snapshot config under lock */
327	    char api_key[128], llm_host[128], llm_path[128], llm_port[8], model[64];
328	    pthread_mutex_lock(&s_llm_lock);
329	    memcpy(api_key, s_api_key, sizeof(api_key));
330	    memcpy(llm_host, s_llm_host, sizeof(llm_host));
331	    memcpy(llm_path, s_llm_path, sizeof(llm_path));
332	    memcpy(llm_port, s_llm_port, sizeof(llm_port));
333	    memcpy(model, s_model, sizeof(model));
334	    pthread_mutex_unlock(&s_llm_lock);
335	
336	    /* Allocate the response buffer once and hand it directly to the
337	     * TLS layer.  Previously we allocated a separate raw_buf and then
338	     * copied into resp_buf — doubling peak memory usage.  Now the
339	     * resp_buf IS the raw buffer, eliminating the copy. */
340	    size_t raw_cap = AGENT_LLM_STREAM_BUF_SIZE;
341	    if (resp_buf_init(rb, raw_cap) != OK)
342	        return ERROR;
343	
344	    /* OpenAI-compatible format: Authorization: Bearer <key> */
345	    char auth_header[256];
346	    snprintf(auth_header, sizeof(auth_header), "Bearer %s", api_key);
347	
348	    /* Extract provider ID from model string (e.g. "xiaomi/mimo-claw-0301" →
349	     * "xiaomi") Mify gateway requires X-Model-Provider-Id header for routing. */
350	    char provider[64] = { 0 };
351	    const char* slash = strchr(model, '/');
352	    if (slash) {
353	        size_t plen = (size_t)(slash - model);
354	        if (plen >= sizeof(provider))
355	            plen = sizeof(provider) - 1;
356	        memcpy(provider, model, plen);
357	    }
358	
359	    /* "Connection: close" disables vela_tls connection pooling for LLM calls.
360	     * The pool reuses idle TLS sockets, but some LLM gateways (e.g.
361	     * api.xiaomimimo.com) leave the socket half-open after responding: the
362	     * next pooled "Reusing connection" write succeeds yet the read then blocks
363	     * for the whole socket timeout, hanging the agent mid-tool-loop. With
364	     * Connection: close the server tears down after each response, the TLS
365	     * layer sees keep=false, and pool_release drops the slot — every call does
366	     * a fresh handshake (~100ms), negligible next to multi-second LLM latency,
367	     * but eliminates the stall. */
368	    vela_header_t hdrs[] = { { "Authorization", auth_header },
369	        { "Connection", "close" },
370	        { provider[0] ? "X-Model-Provider-Id" : NULL,
371	            provider[0] ? provider : NULL },
372	        { NULL, NULL } };
373	
374	    int status;
375	    int use_tls = (strcmp(llm_port, "443") == 0);
376	
377	    if (use_tls) {
378	        status = vela_https_post_json(llm_host, llm_port, llm_path, hdrs, post_data,
379	            rb->data, raw_cap);
380	    } else {
381	        status = vela_http_post_json(llm_host, llm_port, llm_path, hdrs, post_data,
382	            rb->data, raw_cap);
383	    }
384	
385	    if (status < 0) {
386	        resp_buf_free(rb);
387	        return ERROR;
388	    }
389	
390	    /* Update length — TLS layer NUL-terminated the buffer */
391	    rb->len = strlen(rb->data);
392	
393	    *out_status = status;
394	    return OK;
395	}
396	
397	/* Proxy path via CONNECT tunnel */
398	static int llm_http_via_proxy(const char* post_data, resp_buf_t* rb,
399	    int* out_status)
400	{
401	    /* Snapshot config under lock */
402	    char api_key[128], llm_host[128], llm_path[128], llm_port[8], model[64];
403	    pthread_mutex_lock(&s_llm_lock);
404	    memcpy(api_key, s_api_key, sizeof(api_key));
405	    memcpy(llm_host, s_llm_host, sizeof(llm_host));
406	    memcpy(llm_path, s_llm_path, sizeof(llm_path));
407	    memcpy(llm_port, s_llm_port, sizeof(llm_port));
408	    memcpy(model, s_model, sizeof(model));
409	    pthread_mutex_unlock(&s_llm_lock);
410	
411	    int port = atoi(llm_port);
412	    if (port <= 0)
413	        port = 443;
414	
415	    proxy_conn_t* conn = proxy_conn_open(llm_host, port, 30000);
416	    if (!conn)
417	        return ERROR;
418	
419	    int body_len = (int)strlen(post_data);
420	    char auth_header[256];
421	    snprintf(auth_header, sizeof(auth_header), "Bearer %s", api_key);
422	
423	    /* Extract provider ID from model (e.g. "xiaomi/mimo-claw-0301" → "xiaomi") */
424	    char provider_hdr[128] = { 0 };
425	    const char* slash = strchr(model, '/');
426	    if (slash) {
427	        char provider[64] = { 0 };
428	        size_t plen = (size_t)(slash - model);
429	        if (plen >= sizeof(provider))
430	            plen = sizeof(provider) - 1;
431	        memcpy(provider, model, plen);
432	        snprintf(provider_hdr, sizeof(provider_hdr), "X-Model-Provider-Id: %s\r\n",
433	            provider);
434	    }
435	
436	    char header[1024];
437	    int hlen = snprintf(header, sizeof(header),
438	        "POST %s HTTP/1.1\r\n"
439	        "Host: %s\r\n"
440	        "Content-Type: application/json\r\n"
441	        "Authorization: %s\r\n"
442	        "%s"
443	        "Content-Length: %d\r\n"
444	        "Connection: close\r\n\r\n",
445	        llm_path, llm_host, auth_header, provider_hdr, body_len);
446	
447	    if (proxy_conn_write(conn, header, hlen) < 0 || proxy_conn_write(conn, post_data, body_len) < 0) {
448	        proxy_conn_close(conn);
449	        return ERROR;
450	    }
451	
452	    if (resp_buf_init(rb, AGENT_LLM_STREAM_BUF_SIZE) != OK) {
453	        proxy_conn_close(conn);
454	        return ERROR;
455	    }
456	
457	    /* 1 KB read chunk instead of 4 KB: llm_http_direct already has a 1 KB
458	     * header buffer on its stack, and the whole LLM call runs on the 32 KB
459	     * agent-loop thread.  Smaller chunks keep peak stack headroom. */
460	    char tmp[1024];
461	    while (1) {
462	        int n = proxy_conn_read(conn, tmp, sizeof(tmp), 120000);
463	        if (n <= 0)
464	            break;
465	        if (resp_buf_append(rb, tmp, (size_t)n) != OK) {
466	            syslog(LOG_ERR, "[%s] resp_buf_append OOM, truncating\n", TAG);
467	            break;
468	        }
469	    }
470	    proxy_conn_close(conn);
471	
472	    /* Parse status from raw HTTP response */
473	    *out_status = 0;
474	    if (rb->len > 5 && strncmp(rb->data, "HTTP/", 5) == 0) {
475	        const char* sp = strchr(rb->data, ' ');
476	        if (sp)
477	            *out_status = atoi(sp + 1);
478	    }
479	
480	    /* Strip HTTP header, keep body */
481	    char* body = strstr(rb->data, "\r\n\r\n");
482	    if (body) {
483	        body += 4;
484	        size_t blen = rb->len - (size_t)(body - rb->data);
485	        memmove(rb->data, body, blen);
486	        rb->len = blen;
487	        rb->data[rb->len] = '\0';
488	    }
489	
490	    return OK;
491	}
492	
493	int llm_http_call(const char* post_data, resp_buf_t* rb,
494	    int* out_status)
495	{
496	    /* For plain HTTP endpoints (port != 443), always use direct path.
497	     * The proxy does CONNECT + TLS which fails on non-TLS endpoints.
498	     * Non-TLS HTTP endpoints (port != 443) are reachable
499	     * directly without a proxy anyway. */
500	    int use_tls;
501	    pthread_mutex_lock(&s_llm_lock);
502	    use_tls = (strcmp(s_llm_port, "443") == 0);
503	    pthread_mutex_unlock(&s_llm_lock);
504	
505	#ifdef CONFIG_AI_AGENT_NET_RPMSG
506	    int retry_max = network_get_retry_max();
507	    int retry_base = network_get_retry_base_sec();
508	    int ret = ERROR;
509	
510	    for (int attempt = 0; attempt <= retry_max; attempt++) {
511	        if (attempt > 0) {
512	            /* Check network state before retrying */
513	            if (network_get_state() != NET_STATE_CONNECTED) {
514	                syslog(LOG_WARNING, "[llm] Network down, skip retry %d\n", attempt);
515	                break;
516	            }
517	            int delay = retry_base * (1 << (attempt - 1));
518	            syslog(LOG_INFO, "[llm] Retry %d/%d after %ds\n", attempt, retry_max, delay);
519	            sleep(delay);
520	        }
521	
522	        if (use_tls && http_proxy_is_enabled()) {
523	            ret = llm_http_via_proxy(post_data, rb, out_status);
524	        } else {
525	            ret = llm_http_direct(post_data, rb, out_status);
526	        }
527	
528	        if (ret == OK) {
529	            return OK;
530	        }
531	
532	        syslog(LOG_WARNING, "[llm] HTTP call failed (attempt %d/%d)\n",
533	            attempt + 1, retry_max + 1);
534	    }
535	
536	    /* All retries failed — notify user */
537	    syslog(LOG_ERR, "[llm] All %d retries failed\n", retry_max + 1);
538	    {
539	        agent_msg_t notify;
540	        memset(&notify, 0, sizeof(notify));
541	        strncpy(notify.channel, "cli", sizeof(notify.channel) - 1);
542	        notify.content = strdup("网络请求失败，请检查蓝牙连接");
543	        if (notify.content) {
544	            if (message_bus_push_outbound(&notify) != OK) {
545	                free(notify.content);
546	            }
547	        }
548	    }
549	    return ERROR;
550	#else
551	    if (use_tls && http_proxy_is_enabled())
552	        return llm_http_via_proxy(post_data, rb, out_status);
553	    return llm_http_direct(post_data, rb, out_status);
554	#endif
555	}
