558	
559	/* Extract text from OpenAI response format: choices[0].message.content */
560	void extract_text(cJSON* root, char* buf, size_t size)
561	{
562	    buf[0] = '\0';
563	    cJSON* choices = cJSON_GetObjectItem(root, "choices");
564	    if (!choices || !cJSON_IsArray(choices))
565	        return;
566	
567	    cJSON* first = choices->child;
568	    if (!first)
569	        return;
570	
571	    cJSON* message = cJSON_GetObjectItem(first, "message");
572	    if (!message)
573	        return;
574	
575	    cJSON* content = cJSON_GetObjectItem(message, "content");
576	    if (!content || !cJSON_IsString(content))
577	        return;
578	
579	    size_t tlen = strlen(content->valuestring);
580	    size_t copy = (tlen < size - 1) ? tlen : size - 1;
581	    memcpy(buf, content->valuestring, copy);
582	    buf[copy] = '\0';
583	}
