585	/* ── Public: simple chat ──────────────────────────────────── */
586	
587	int llm_chat(const char* system_prompt, const char* messages_json,
588	    char* response_buf, size_t buf_size)
589	{
590	    /* Snapshot config under lock */
591	    char model[64], api_key[128], llm_host[128];
592	    pthread_mutex_lock(&s_llm_lock);
593	    memcpy(model, s_model, sizeof(model));
594	    memcpy(api_key, s_api_key, sizeof(api_key));
595	    memcpy(llm_host, s_llm_host, sizeof(llm_host));
596	    pthread_mutex_unlock(&s_llm_lock);
597	
598	    if (api_key[0] == '\0') {
599	        snprintf(response_buf, buf_size, "Error: No API key configured");
600	        return ERROR;
601	    }
602	
603	    cJSON* body = cJSON_CreateObject();
604	    cJSON_AddStringToObject(body, "model",
605	        model_name_for_api(model, llm_host));
606	
607	    if (is_openai_compat_host(llm_host))
608	        cJSON_AddNumberToObject(body, "max_completion_tokens",
609	            AGENT_LLM_MAX_TOKENS_OPENAI);
610	    else
611	        cJSON_AddNumberToObject(body, "max_tokens", AGENT_LLM_MAX_TOKENS);
612	
613	    cJSON* messages = cJSON_Parse(messages_json);
614	    if (!messages)
615	        messages = cJSON_CreateArray();
616	
617	    /* Prepend system message (OpenAI format) */
618	    cJSON* sys_msg = cJSON_CreateObject();
619	    cJSON_AddStringToObject(sys_msg, "role", "system");
620	    cJSON_AddStringToObject(sys_msg, "content", system_prompt);
621	    cJSON_InsertItemInArray(messages, 0, sys_msg);
622	
623	    cJSON_AddItemToObject(body, "messages", messages);
624	
625	    char* post_data = cJSON_PrintUnformatted(body);
626	    cJSON_Delete(body);
627	    if (!post_data) {
628	        snprintf(response_buf, buf_size, "Error: Failed to build request");
629	        return ERROR;
630	    }
631	
632	    syslog(LOG_INFO, "[%s] Calling LLM API (model: %s, host: %s, %d bytes)\n",
633	        TAG, model, llm_host, (int)strlen(post_data));
634	
635	    resp_buf_t rb = { 0 };
636	    int status = 0;
637	    int err = ERROR;
638	    int retry;
639	
640	    for (retry = 0; retry <= AGENT_LLM_MAX_RETRIES; retry++) {
641	        if (retry > 0) {
642	            unsigned int delay = AGENT_LLM_RETRY_BASE_SEC << (retry - 1);
643	            syslog(LOG_WARNING, "[%s] Rate limited (429), retry %d/%d after %us\n",
644	                TAG, retry, AGENT_LLM_MAX_RETRIES, delay);
645	            sleep(delay);
646	        }
647	
648	        rb.len = 0;
649	        status = 0;
650	        err = llm_http_call(post_data, &rb, &status);
651	
652	        if (err != OK) {
653	            resp_buf_free(&rb);
654	            free(post_data);
655	            snprintf(response_buf, buf_size, "Error: HTTP request failed");
656	            return err;
657	        }
658	
659	        if (status != 429)
660	            break;
661	
662	        resp_buf_free(&rb);
663	        memset(&rb, 0, sizeof(rb));
664	    }
665	
666	    free(post_data);
667	
668	    if (status != 200) {
669	        snprintf(response_buf, buf_size, "API error (HTTP %d): %.200s", status,
670	            rb.data ? rb.data : "");
671	        resp_buf_free(&rb);
672	        return ERROR;
673	    }
674	
675	    cJSON* root = cJSON_Parse(rb.data);
676	    resp_buf_free(&rb);
677	
678	    if (!root) {
679	        snprintf(response_buf, buf_size, "Error: Failed to parse response");
680	        return ERROR;
681	    }
682	
683	    extract_text(root, response_buf, buf_size);
684	    cJSON_Delete(root);
685	
686	    if (response_buf[0] == '\0')
687	        snprintf(response_buf, buf_size, "No response from LLM API");
688	    else
689	        syslog(LOG_INFO, "[%s] LLM response: %d bytes\n", TAG,
690	            (int)strlen(response_buf));
691	
692	    return OK;
693	}
