711	    memcpy(llm_host, s_llm_host, sizeof(llm_host));
712	    pthread_mutex_unlock(&s_llm_lock);
713	
714	    if (api_key[0] == '\0') {
715	        return ERROR;
716	    }
717	
718	    cJSON* body = cJSON_CreateObject();
719	
720	    cJSON_AddStringToObject(body, "model",
721	        model_name_for_api(model, llm_host));
722	
723	    if (is_openai_compat_host(llm_host)) {
724	        cJSON_AddNumberToObject(body, "max_completion_tokens",
725	            AGENT_LLM_MAX_TOKENS_OPENAI);
726	    } else {
727	        cJSON_AddNumberToObject(body, "max_tokens",
728	            AGENT_LLM_MAX_TOKENS);
729	    }
730	
731	    /* Clone messages and prepend system message */
732	    cJSON* msgs = cJSON_Duplicate(messages, 1);
733	    cJSON* sys_msg = cJSON_CreateObject();
734	
735	    cJSON_AddStringToObject(sys_msg, "role", "system");
736	    cJSON_AddStringToObject(sys_msg, "content", system_prompt);
737	    cJSON_InsertItemInArray(msgs, 0, sys_msg);
738	    cJSON_AddItemToObject(body, "messages", msgs);
739	
740	    /* Convert tools to OpenAI format */
741	    cJSON* tools_arr = build_openai_tools_array(tools_json);
742	
743	    if (tools_arr) {
744	        cJSON_AddItemToObject(body, "tools", tools_arr);
745	    }
746	
747	    char* post_data = cJSON_PrintUnformatted(body);
748	
749	    cJSON_Delete(body);
750	    if (!post_data) {
751	        return ERROR;
752	    }
753	
754	    syslog(LOG_INFO,
755	        "[%s] OpenAI API with tools (model: %s, %d bytes)\n",
756	        TAG, model, (int)strlen(post_data));
757	
758	    resp_buf_t rb = { 0 };
759	    int status = 0;
760	    int err = ERROR;
761	    int retry;
762	
763	    for (retry = 0; retry <= AGENT_LLM_MAX_RETRIES; retry++) {
764	        if (retry > 0) {
765	            unsigned int delay = AGENT_LLM_RETRY_BASE_SEC << (retry - 1);
766	            syslog(LOG_WARNING, "[%s] Rate limited (429), retry %d/%d after %us\n",
767	                TAG, retry, AGENT_LLM_MAX_RETRIES, delay);
768	            sleep(delay);
769	        }
770	
771	        rb.len = 0;
772	        status = 0;
773	        err = llm_http_call(post_data, &rb, &status);
774	
775	        if (err != OK) {
776	            resp_buf_free(&rb);
777	            free(post_data);
778	            return err;
779	        }
780	
781	        if (status != 429)
782	            break;
783	
784	        resp_buf_free(&rb);
785	        memset(&rb, 0, sizeof(rb));
786	    }
787	
788	    free(post_data);
789	
790	    if (status != 200) {
791	        syslog(LOG_ERR, "[%s] API error %d: %.500s\n", TAG, status,
792	            rb.data ? rb.data : "");
793	        resp_buf_free(&rb);
794	        return ERROR;
795	    }
796	
797	    cJSON* root = cJSON_Parse(rb.data);
798	
799	    resp_buf_free(&rb);
800	    if (!root) {
801	        syslog(LOG_ERR, "[%s] Failed to parse API JSON\n", TAG);
802	        return ERROR;
803	    }
804	
805	    /* Extract from OpenAI response */
806	    cJSON* choices = cJSON_GetObjectItem(root, "choices");
807	
808	    if (!choices || !cJSON_IsArray(choices) || !choices->child) {
809	        cJSON_Delete(root);
810	        return ERROR;
811	    }
812	
813	    cJSON* choice = choices->child;
814	    cJSON* finish = cJSON_GetObjectItem(choice, "finish_reason");
815	
816	    resp->tool_use = (finish && cJSON_IsString(finish)
817	        && strcmp(finish->valuestring, "tool_calls") == 0);
818	
819	    cJSON* message = cJSON_GetObjectItem(choice, "message");
820	
