1534	/* Classify an Agent reply text into a coarse card category so the
1535	 * left color bar gives a glanceable cue.  Matching is intentionally
1536	 * simple (case-insensitive substring) — this is a visual hint, not
1537	 * a parser.  Returns the palette color for the matched category. */
1538	static uint32_t chat_view_classify_reply(const char* text)
1539	{
1540	    if (!text || !*text) {
1541	        return LVGL_UI_CARD_COLOR_PLAIN;
1542	    }
1543	
1544	    /* Build a lowercase copy (ASCII only; CJK passes through untouched)
1545	     * so substring checks are case-insensitive for the latin keywords. */
1546	    char buf[LVGL_UI_MSG_MAX_LEN];
1547	    size_t i;
1548	    for (i = 0; i < sizeof(buf) - 1 && text[i]; i++) {
1549	        buf[i] = (text[i] >= 'A' && text[i] <= 'Z') ? (text[i] + 32) : text[i];
1550	    }
1551	    buf[i] = '\0';
1552	
1553	    /* Conclusion: explicit yes/no or recommendation phrasing */
1554	    if (strstr(buf, "yes") || strstr(buf, " no") || strstr(buf, "no.") ||
1555	        strstr(buf, "no,") || strstr(buf, "\xe5\x80\xbc\xe5\xbe\x97") /* 值得 */ ||
1556	        strstr(buf, "\xe4\xb8\x8d\xe5\xbb\xba\xe8\xae\xae") /* 不建议 */ ||
1557	        strstr(buf, "\xe5\xbb\xba\xe8\xae\xae") /* 建议 */ ) {
1558	        return LVGL_UI_CARD_COLOR_CONCLUSION;
1559	    }
1560	
1561	    /* Structured: Gerrit change status keywords (latin) or 状态: */
1562	    if (strstr(buf, "merged") || strstr(buf, "abandoned") ||
1563	        strstr(buf, "status:") || strstr(buf, "\xe7\x8a\xb6\xe6\x80\x81") /* 状态 */ ) {
1564	        return LVGL_UI_CARD_COLOR_STRUCTURED;
1565	    }
1566	
1567	    /* Jira: workflow status or assignee fields */
1568	    if (strstr(buf, "more info") || strstr(buf, "assignee") ||
1569	        strstr(buf, "\xe7\xbb\x8f\xe5\x8a\x9e\xe4\xba\xba") /* 经办人 */ ||
1570	        strstr(buf, "jira") ) {
1571	        return LVGL_UI_CARD_COLOR_JIRA;
1572	    }
1573	
1574	    return LVGL_UI_CARD_COLOR_PLAIN;
1575	}
