637	/**
638	 * Copy text into a fixed buffer with UTF-8-aware truncation.  Copies at most
639	 * dst_size-1 bytes, then if the cut lands inside a multi-byte UTF-8 sequence
640	 * (leading byte 0xC0..0xF4 not followed by enough continuation bytes 0x80..0xBF),
641	 * trims back to the last complete character.  Always NUL-terminates.
642	 *
643	 * This prevents a half-cut Chinese char from rendering as a replacement glyph
644	 * at the end of a truncated Agent reply.
645	 */
646	static void chat_view_copy_text(char* dst, const char* src, size_t dst_size)
647	{
648	    if (dst_size == 0) return;
649	    size_t n = strnlen(src, dst_size - 1);
650	    memcpy(dst, src, n);
651	    dst[n] = '\0';
652	
653	    /* If we filled the buffer, the last char may be incomplete.  Walk back
654	     * from the end to find a UTF-8 leading byte and check its expected length
655	     * against the remaining bytes. */
656	    if (n < dst_size - 1) return;          /* src fit fully, no truncation */
657	    size_t i = n;
658	    while (i > 0) {
659	        unsigned char c = (unsigned char)dst[i - 1];
660	        if ((c & 0xC0) != 0x80) break;     /* not a continuation byte */
661	        i--;
662	    }
663	    if (i == 0) return;                     /* all continuation bytes? give up */
664	    unsigned char lead = (unsigned char)dst[i - 1];
665	    size_t need;
666	    if      ((lead & 0x80) == 0x00) need = 1;   /* ASCII */
667	    else if ((lead & 0xE0) == 0xC0) need = 2;
668	    else if ((lead & 0xF0) == 0xE0) need = 3;
669	    else if ((lead & 0xF8) == 0xF0) need = 4;
670	    else { dst[i - 1] = '\0'; return; }         /* invalid lead, cut it */
671	    if (n - (i - 1) < need) {
672	        dst[i - 1] = '\0';                      /* incomplete seq, trim it */
673	    }
674	}
