676	/**
677	 * Add a message to the chat history ring buffer.
678	 *
679	 * When count < CHAT_HISTORY_MAX, writes at head and increments count.
680	 * When count == CHAT_HISTORY_MAX, overwrites the oldest message and
681	 * deletes its LVGL bubble widget if present.
682	 *
683	 * Text is truncated to LVGL_UI_MSG_MAX_LEN - 1 bytes with explicit
684	 * NUL termination (rule coding-9), UTF-8-aware so a multi-byte char is
685	 * never split in half.
686	 *
687	 * Returns pointer to the newly written slot (inside the ring buffer,
688	 * no stack allocation of chat_msg_t — rule coding-6).
689	 */
690	static chat_msg_t* chat_history_add(chat_history_t* h, const char* text, bool is_user)
691	{
692	    chat_msg_t* slot = &h->msgs[h->head];
693	
694	    /* When buffer is full, recycle the oldest slot */
695	    if (h->count == CHAT_HISTORY_MAX) {
696	        if (slot->bubble) {
697	            lv_obj_del(slot->bubble);
698	            slot->bubble = NULL;
699	        }
700	    } else {
701	        h->count++;
702	    }
703	
704	    /* Write message text with UTF-8-aware truncation */
705	    chat_view_copy_text(slot->text, text, LVGL_UI_MSG_MAX_LEN);
706	
707	    slot->is_user = is_user;
708	    slot->bubble = NULL;
709	
710	    h->head = (h->head + 1) % CHAT_HISTORY_MAX;
711	
712	    return slot;
713	}
