489	static void* lv_loop_thread(void* arg)
490	{
491	    struct sched_param sp;
492	    uint32_t frames = 0;
493	
494	    (void)arg;
495	
496	    /* LV_USE_LOG is on but LV_LOG_PRINTF is off, so every LVGL log line —
497	     * including "Asserted at expression: ... (Out of memory)" — was being
498	     * discarded.  Route them to syslog so an assert is visible before
499	     * lv_assert_handler() takes the system down. */
500	    lv_log_register_print_cb(lvgl_log_cb);
501	
502	    /* The loop thread was created with the default pthread priority
503	     * (inherited), so TLS / LLM dispatch / TTS work preempts it.  A frame
504	     * that is preempted mid-flush holds lvgl_ui_lock() for that whole
505	     * time, and every cross-thread LVGL caller (agent reply path, pet
506	     * state, PTT) blocks behind it.  Run at the UI priority instead. */
507	    sp.sched_priority = AGENT_LVGL_UI_PRIO;
508	    int prc = sched_setparam(0, &sp);
509	    syslog(LOG_INFO, "[%s] LVGL loop prio -> %d (rc=%d)\n",
510	           TAG, AGENT_LVGL_UI_PRIO, prc);
511	
512	    /* Stall detector — see ui_watchdog_thread().  Give it an explicit 8 KB
513	     * stack: CONFIG_PTHREAD_STACK_DEFAULT is 2048 here, which is marginal for
514	     * one snprintf, and the previous run's watchdog never printed a byte while
515	     * every other thread kept logging — a too-small stack is the likeliest
516	     * reason.  The creation result is logged so a silent watchdog can no
517	     * longer be confused with a wedged scheduler. */
518	    {
519	      pthread_attr_t wattr;
520	      int crc = -1;
521	
522	      if (pthread_attr_init(&wattr) == 0)
523	        {
524	          struct sched_param wsp;
525	
526	          (void)pthread_attr_setstacksize(&wattr, 8192);
527	          wsp.sched_priority = 20;   /* above the LVGL loop (45) */
528	          (void)pthread_attr_setschedparam(&wattr, &wsp);
529	          (void)pthread_attr_setschedpolicy(&wattr, SCHED_FIFO);
530	          (void)pthread_attr_setinheritsched(&wattr, PTHREAD_EXPLICIT_SCHED);
531	          crc = pthread_create(&s_lv_wd_tid, &wattr, ui_watchdog_thread, NULL);
532	          (void)pthread_attr_destroy(&wattr);
533	        }
534	
535	      syslog(LOG_INFO, "[%s] watchdog create rc=%d\n", TAG, crc);
536	    }
537	
538	    while (s_lv_loop_running) {
539	        uint32_t idle;
540	        struct timespec t0;
541	        struct timespec t1;
542	        long ms;
543	
544	        /* Serialize with cross-thread lv_async_call()/lv_timer_create()
545	         * users.  CONFIG_LV_USE_OS=0 means LVGL does no locking itself. */
546	        clock_gettime(CLOCK_MONOTONIC, &t0);
547	        lvgl_ui_lock();
548	        idle = lv_timer_handler();
549	        lvgl_ui_unlock();
550	        s_lv_frames++;
551	        clock_gettime(CLOCK_MONOTONIC, &t1);
552	
553	        ms = (t1.tv_sec - t0.tv_sec) * 1000
554	           + (t1.tv_nsec - t0.tv_nsec) / 1000000;
555	
556	        /* One slow frame is the first symptom of a wedged render/flush;
557	         * log it while the board is still talking. */
558	        if (ms >= 300)
559	          {
560	            syslog(LOG_WARNING, "[%s] handler %ldms idle=%u\n",
561	                   TAG, ms, (unsigned)idle);
562	          }
563	
564	        /* Heartbeat: ~every 5 s at the normal cadence.  Silence after a
565	         * hang means the LVGL thread itself stopped, not just the caller. */
566	        if (++frames % 20 == 0)
567	          {
568	            char hb[192];
569	            int hn;
570	
571	#if defined(CONFIG_STACK_COLORATION)
572	            /* Stack high-water for this thread: if the reply-card build
573	             * overflows the 64 KB LVGL stack, the log simply stops with no
574	             * message, so surface the headroom while the board still talks. */
575	            struct stackinfo_s si = {0};
576	            size_t used = 0;
577	
578	            if (nxsched_get_stackinfo(0, &si) == 0 && si.adj_stack_size > 0)
579	              {
580	                used = up_check_tcbstack(nxsched_self(), si.adj_stack_size);
581	              }
582	
583	            hn = snprintf(hb, sizeof(hb),
584	                          "\r\n[lvgl_ui] hb frames stack %lu %lu wd %lu st %d pr %d "
585	                          "lvl %lu/%lu/%lu\r\n",
586	                          (unsigned long)frames, (unsigned long)used,
587	                          (unsigned long)s_wd_ticks, s_wd_stage, s_wd_prio,
588	                          (unsigned long)lv_dbg_layout_outer,
589	                          (unsigned long)lv_dbg_layout_calls,
590	                          (unsigned long)lv_dbg_refr_calls);
