592	            hn = snprintf(hb, sizeof(hb),
593	                          "\r\n[lvgl_ui] hb frames %lu 0 wd %lu st %d pr %d\r\n",
594	                          (unsigned long)frames, (unsigned long)s_wd_ticks,

