334	
335	static void apply_state_async_cb(void *data)
336	{
337	  enum pet_state st = (enum pet_state)(intptr_t)data;
338	  if (!s_pet.initialized || !s_pet.sprite) return;
339	
340	  s_pet.state = st;
341	
342	  /* Reset the sprite to a clean base frame; per-state anim re-derives it. */
343	  lv_image_set_src(s_pet.sprite, s_frames->base);
344	  lv_obj_set_style_translate_x(s_pet.sprite, 0, 0);  /* clear any shake offset */
345	  lv_obj_set_style_translate_y(s_pet.sprite, 0, 0);  /* clear any float offset */
346	  lv_obj_set_style_opa(s_pet.sprite, LV_OPA_COVER, 0);
347	
348	  if (s_pet.label) {
349	    if (st == PET_STATE_ERROR && s_error_text[0] != '\0') {
350	      lv_label_set_text(s_pet.label, s_error_text);
351	      lv_obj_set_style_text_color(s_pet.label,
352	                                  lv_color_hex(UI_PAL_ERROR), 0);
353	    } else {
354	      lv_label_set_text(s_pet.label, display_text_for(st));
355	      lv_obj_set_style_text_color(s_pet.label,
356	                                  lv_color_hex(UI_PAL_TEXT_DIM), 0);
357	    }
358	  }
359	
360	  /* Leaving ERROR clears the reason: a later, unrelated error must not
361	   * resurrect an old explanation. */
362	  if (st != PET_STATE_ERROR) {
363	    s_error_text[0] = '\0';
364	  }
365	  if (s_pet.status_dot) {
366	    lv_obj_set_style_bg_color(s_pet.status_dot, lv_color_hex(s_state_color[st]), 0);
367	    /* Legend (idle) has no status dot; busy states show it. */
368	    if (st == PET_STATE_IDLE)
369	      lv_obj_add_flag(s_pet.status_dot, LV_OBJ_FLAG_HIDDEN);
370	    else
371	      lv_obj_remove_flag(s_pet.status_dot, LV_OBJ_FLAG_HIDDEN);
372	  }
373	
374	  start_anim_for(st);
375	  syslog(LOG_INFO, "[%s] state → %s\n", TAG, s_state_text[st]);
376	}
