145	/* ── LVGL thread-safety lock ─────────────────────────────────────
146	 *
147	 * This build has CONFIG_LV_USE_OS=0, so LVGL has no internal locking:
148	 * its timer list, object tree and lv_malloc heap are plain
149	 * unsynchronized globals.  lv_loop_thread() calls lv_timer_handler(),
150	 * but every other thread (agent loop, outbound dispatch, PTT button,
151	 * cmd channel, notify) reaches LVGL through lv_async_call() /
152	 * lv_timer_create().  Without a lock those calls race the handler:
153	 * lv_timer_create() links the new timer into the global list *before*
154	 * filling in its fields, so the handler can run a half-built timer and
155	 * read a garbage user_data pointer.  Observed on BK7258 hardware:
156	 * lv_async_timer_cb's `ldmia` on an unaligned user_data -> UsageFault
157	 * (CFSR=0x01000000 UNALIGNED) in the ai_agent process, which RPTUN
158	 * escalates to "Panic by remote core: ap" and resets AP.
159	 *
160	 * Hold this lock around any LVGL entry point called from a non-LVGL
161	 * thread, and around lv_timer_handler() itself.
162	 *
163	 * Recursion is required: LVGL-thread callbacks (pet_idle_timer_cb,
164	 * standby_timer_cb) themselves queue async calls.  CONFIG_PTHREAD_MUTEX_TYPES
165	 * is disabled in this build, so a recursive pthread mutex is unavailable;
166	 * emulate it with owner + depth instead.
167	 */
168	static pthread_mutex_t s_lvgl_lock = PTHREAD_MUTEX_INITIALIZER;
169	static volatile pthread_t s_lvgl_lock_owner;  /* 0 = not held */
170	static volatile int s_lvgl_lock_depth;
171	
172	void lvgl_ui_lock(void)
173	{
174	    pthread_t self = pthread_self();
175	    struct timespec t0;
176	    struct timespec t1;
177	    bool wait_logged = false;
178	    long next_raw = 5000;   /* periodic raw report while waiting */
179	
180	    /* Fast path: this thread already owns the lock.  Only the owner ever
181	     * stores its tid here, and unlock() clears it before releasing, so a
182	     * stale value from a previous owner can never match a non-owner. */
183	    if (s_lvgl_lock_owner != (pthread_t)0 &&
184	        pthread_equal(s_lvgl_lock_owner, self))
185	      {
186	        s_lvgl_lock_depth++;
187	        return;
188	      }
189	
190	    /* Try-then-sleep instead of a plain blocking lock so a stuck LVGL
191	     * thread can be identified: whoever holds the lock too long is named
192	     * in the log before the caller gives up waiting. */
193	    clock_gettime(CLOCK_MONOTONIC, &t0);
194	    while (pthread_mutex_trylock(&s_lvgl_lock) != 0)
195	      {
196	        clock_gettime(CLOCK_MONOTONIC, &t1);
197	        long ms = (t1.tv_sec - t0.tv_sec) * 1000
198	                + (t1.tv_nsec - t0.tv_nsec) / 1000000;
199	
200	        if (!wait_logged && ms >= 500)
201	          {
202	            syslog(LOG_WARNING,
