123	/* ---------- LCG (per-particle deterministic pseudo-noise) ---------- */
124	
125	static inline int32_t lcg_next(uint32_t *s)
126	{
127	  *s = (*s * 1103515765u + 12345u) & 0x7fffffffu;
128	  return (int32_t)(*s >> 15) - 16384;   /* [-16384, 16383] */
129	}
130	
131	/* ---------- physics step (runs in LVGL thread via timer) ---------- */
132	
133	static void physics_step(void)
134	{
135	  const phys_t *ph = &s_phys[s_pf.state];
136	  int32_t cx = s_pf.cx, cy = s_pf.cy, R_sq = s_pf.R_sq;
137	  int32_t damp = ph->damp;
138	  int32_t perturb = ph->perturb;
139	  int32_t swirl = ph->swirl;
140	  int32_t radial = ph->radial;
141	
142	  for (int i = 0; i < N_PARTICLES; i++)
143	    {
144	      struct particle_s *p = &s_pf.p[i];
145	      int32_t dx = p->x - cx;
146	      int32_t dy = p->y - cy;
147	
148	      /* LCG noise → small velocity kick (perturb in q8; noise normalized to ~[-1,1] px). */
149	      int32_t nx = lcg_next(&p->lcg);
150	      int32_t ny = lcg_next(&p->lcg);
151	      p->vx += (nx * perturb) / 16384;
152	      p->vy += (ny * perturb) / 16384;
153	
154	      /* Swirl: tangential bias ∝ radial offset (unnormalized → faster swirl
155	       * farther out, reads as rotation). tang = (-dy, dx). */
156	      p->vx += (-dy * swirl) / 64;
157	      p->vy += ( dx * swirl) / 64;
158	
159	      /* Radial bias: outward (+) pulls particles to the rim, inward (-) sucks
160	       * them toward the core. */
161	      p->vx += (dx * radial) / 64;
162	      p->vy += (dy * radial) / 64;
163	
164	      /* Damping. */
165	      p->vx = (p->vx * damp) / 256;
166	      p->vy = (p->vy * damp) / 256;
167	
168	      /* Speed clamp so chaos stays bounded. */
169	      int32_t vmax = 3 * ONE_PX;
170	      if (p->vx >  vmax) p->vx =  vmax;
171	      if (p->vx < -vmax) p->vx = -vmax;
172	      if (p->vy >  vmax) p->vy =  vmax;
173	      if (p->vy < -vmax) p->vy = -vmax;
174	
175	      /* Advance. */
176	      int32_t nxp = p->x + (p->vx >> VEL_Q);
177	      int32_t nyp = p->y + (p->vy >> VEL_Q);
178	
179	      /* Round-bound bounce: if next step leaves the disc, reverse velocity
180	       * (cheap reflection) and don't move this tick. dist_sq in pixel units
181	       * fits in int32 (max ~217k). */
182	      int32_t ddx = nxp - cx;
183	      int32_t ddy = nyp - cy;
184	      int32_t dsq = ddx * ddx + ddy * ddy;
185	      if (dsq > R_sq)
186	        {
187	          p->vx = -p->vx;
188	          p->vy = -p->vy;
189	        }
190	      else
191	        {
192	          p->x = nxp;
193	          p->y = nyp;
194	        }
195	
196	      /* Render — only invalidate when the integer pixel position actually
197	       * changes.  Particles move sub-pixel most ticks (q8 velocity), so an
198	       * unconditional set_pos would invalidate 18 regions every 33 ms even
199	       * when nothing visibly moved.  On flush paths that can't keep up
200	       * (qemu goldfish headless fb) the constant re-invalidation starves the
201	       * flush so the screen never reaches the framebuffer.  Skipping no-op
202	       * moves collapses invalidations to only real pixel crossings. */
203	      lv_obj_t *o = s_pf.particles[i];
204	      if (o)
205	        {
206	          int32_t rx = p->x - (PARTICLE_DIAM / 2);
207	          int32_t ry = p->y - (PARTICLE_DIAM / 2);
208	          if (rx != p->last_rx || ry != p->last_ry)
209	            {
210	              lv_obj_set_pos(o, rx, ry);
211	              p->last_rx = rx;
212	              p->last_ry = ry;
213	            }
214	        }
215	    }
216	
217	  /* Core pulse: opacity breathing driven by tick (no lv_anim to keep the
218	   * pulsing phase-locked to the physics tick). */
219	  if (s_pf.core)
220	    {
221	      uint32_t t = s_pf.tick & 63;            /* 0..63 */
222	      int32_t tri = (t < 32) ? t : (63 - t);  /* triangle 0..31 */
223	      lv_opa_t opa = LV_OPA_60 + (tri * (LV_OPA_COVER - LV_OPA_60)) / 31;
224	      lv_obj_set_style_opa(s_pf.core, opa, 0);
225	    }
226	
227	  s_pf.tick++;
228	}
