271	static int bk7258_rptun_stop(struct rptun_dev_s *dev)
272	{
273	  struct bk7258_rptun_dev_s *priv =
274	    container_of(dev, struct bk7258_rptun_dev_s, rptun);
275	  irqstate_t flags;
276	
277	  /* The generic RPTUN layer owns VirtIO/RPMsg destruction.  The board layer
278	   * only owns the Mailbox coalescing state, so make both directions eligible
279	   * for the next generation before remoteproc_shutdown() removes devices. */
280	
281	  flags = enter_critical_section();
282	  priv->shmem->mbox_pending[0] = 0;
283	  priv->shmem->mbox_pending[1] = 0;
284	  bk7258_rptun_barrier();
285	  leave_critical_section(flags);
286	  return 0;
287	}
