326	static int bk7258_rptun_notify(struct rptun_dev_s *dev, uint32_t vqid)
327	{
328	  struct bk7258_rptun_dev_s *priv =
329	    container_of(dev, struct bk7258_rptun_dev_s, rptun);
330	  int peer = priv->master ? 1 : 0;
331	  irqstate_t flags;
332	  int ret;
333	
334	  (void)vqid;
335	  bk7258_rptun_barrier();
336	  /* Every Mailbox entry is an idempotent request to scan all virtqueues.
337	   * Keep at most one doorbell outstanding in each direction.  This explicit
338	   * latch, rather than the instantaneous FIFO-full state, makes coalescing
339	   * race-free: the receiver clears it before scanning the virtqueues.
340	   */
341	
342	  flags = enter_critical_section();
343	  if (priv->shmem->mbox_pending[peer] != 0)
344	    {
345	      leave_critical_section(flags);
346	      return 0;
347	    }
348	
349	  priv->shmem->mbox_pending[peer] = 1;
350	  bk7258_rptun_barrier();
351	
352	  /* A doorbell that returns -EBUSY means the peer FIFO was momentarily full
353	   * (the peer had not yet drained a previous kick).  Losing this kick would
354	   * leave data in the vring with no scan and deadlock the uart_rpmsg ACK
355	   * round-trip, so spin-retry while holding the latch until the kick lands. */
356	
357	  ret = bk7258_mbox_notify(peer, RPTUN_NOTIFY_ALL);
358	  while (ret == -EBUSY)
359	    {
360	      volatile unsigned int spin;
361	
362	      for (spin = 0; spin < 200; spin++)
363	        {
364	          __asm__ volatile ("nop");
365	        }
366	
367	      ret = bk7258_mbox_notify(peer, RPTUN_NOTIFY_ALL);
368	    }
369	
370	  if (ret < 0)
371	    {
372	      priv->shmem->mbox_pending[peer] = 0;
373	      bk7258_rptun_barrier();
374	    }
375	
376	  leave_critical_section(flags);
377	  return ret;
378	}
