10	 *
11	 * The split keeps the two colours from ever fighting for meaning: green is
12	 * "how is it going", red is "come and look".  Red and green are never on
13	 * together.
14	 *
15	 * This module registers as a remote_ctrl observer and knows nothing about
16	 * the channel beyond the state vocabulary it is handed.  A product with a
17	 * screen would register a different observer and leave this one alone.
18	 ****************************************************************************/
19	
20	#include <nuttx/config.h>
21	
22	#include <errno.h>
23	#include <stdio.h>
24	#include <string.h>
25	#include <unistd.h>
26	
27	#include "board.h"
