30	/* The remote_ctrl observer surface.  Declared here rather than included:
31	 * the board layer must not reach into an application package's internals.
32	 */
33	
34	struct remote_observer_ops_s
35	{
36	  const char *name;
37	  void (*on_state)(const char *text, void *ctx);
38	  void (*on_reply)(const char *text, void *ctx);
39	  void *ctx;
40	};
41	
42	int remote_ctrl_register_observer(const struct remote_observer_ops_s *ops);
43	
44	/****************************************************************************
45	 * Pre-processor Definitions
46	 ****************************************************************************/
47	
48	/* GPIO40 is the red half and GPIO41 the green one.  The slow green blink
49	 * seen at boot is this module's IDLE pattern on GPIO41, not the retired
50	 * heartbeat; the red flicker that used to appear over it was the old
51	 * heartbeat writing GPIO40 once a second from a second owner.
52	 */
53	
54	#define LED_RED_PIN       40
55	#define LED_GREEN_PIN     41
56	#define LED_ACTIVE_HIGH   1
57	
58	#define BLINK_SLOW_MS     1000
59	#define BLINK_FAST_MS     300
60	#define DONE_HOLD_MS      3000
61	#define TICK_MS           50
62	
63	/****************************************************************************
64	 * Private Data
65	 ****************************************************************************/
66	
67	/* Two colours, two shapes: green is "the board is yours", red is "a human
68	 * is needed".  Solid = settled, blinking = moving -- so idle is solid and
69	 * working blinks, and the red pair follows the same rule: approval waits
70	 * solid, an error blinks.
71	 */
72	enum led_phase_e
73	{
74	  PHASE_IDLE = 0,   /* green solid */
75	  PHASE_WORKING,    /* green blink */
76	  PHASE_APPROVAL,   /* red solid */
77	  PHASE_DONE,       /* green fast blink for DONE_HOLD_MS, then IDLE */
78	  PHASE_ERROR,      /* red blink */
79	};
80	
81	static volatile enum led_phase_e s_phase = PHASE_IDLE;
82	static uint32_t s_phase_left_ms;
83	
84	static void led_write(unsigned int pin, bool on)
85	{
86	  bool high = LED_ACTIVE_HIGH ? on : !on;
87	
88	  bk7258_gpio_write(pin, high);
89	}
90	
91	static const char *phase_name(enum led_phase_e p)
92	{
93	  switch (p)
94	    {
95	      case PHASE_IDLE:    return "IDLE";
96	      case PHASE_WORKING: return "WORKING";
97	      case PHASE_APPROVAL:return "APPROVAL";
98	      case PHASE_DONE:    return "DONE";
99	      case PHASE_ERROR:   return "ERROR";
100	    }
101	  return "?";
102	}
103	
104	static void led_phase_enter(enum led_phase_e p)
105	{
106	  if (p != s_phase)
107	    {
108	      printf("[led] %s -> %s\n", phase_name(s_phase), phase_name(p));
109	    }
110	
111	  s_phase = p;
112	  s_phase_left_ms = (p == PHASE_DONE) ? DONE_HOLD_MS : 0;
113	}
114	
115	/* Classify the bridge's free-form status text into a phase.  The strings
116	 * are the vocabulary remote_ctrl forwards; matching on the two that a
117	 * person has to react to and treating the rest as progress keeps this
118	 * robust when the bridge adds new lines.
119	 */
120	
121	static void led_on_state(const char *text, void *ctx)
122	{
123	  (void)ctx;
124	
125	  if (text == NULL)
126	    {
127	      return;
128	    }
129	
130	  /* DONE is sticky: the reply is followed by more status text
131	   * ("Agent turn completed", the mirrored reply line), and each of those
132	   * would otherwise knock a finished turn back into WORKING and eat the
133	   * three seconds of green the caller is meant to see.
134	   */
135	
136	  if (s_phase == PHASE_DONE)
137	    {
138	      return;
139	    }
140	
141	  if (strncmp(text, "approval required", 17) == 0)
142	    {
143	      printf("[led] by approval: %.60s\n", text);
144	      led_phase_enter(PHASE_APPROVAL);
145	    }
146	  else if (strncmp(text, "Agent turn failed", 17) == 0)
147	    {
148	      printf("[led] by failed: %.60s\n", text);
149	      led_phase_enter(PHASE_ERROR);
150	    }
151	  else if (strncmp(text, "Agent turn", 10) == 0)
152	    {
153	      led_phase_enter(PHASE_DONE);
154	    }
155	  else
156	    {
157	      led_phase_enter(PHASE_WORKING);
158	    }
159	}
160	
161	static void led_on_reply(const char *text, void *ctx)
162	{
163	  (void)text;
164	  (void)ctx;
165	
166	  led_phase_enter(PHASE_DONE);
167	}
168	
169	static const struct remote_observer_ops_s g_led_observer =
170	{
171	  "led", led_on_state, led_on_reply, NULL
172	};
173	
174	/* Driven from the single board-services thread, not one of its own: a
175	 * 50 ms blink loop does not deserve a 2 KB stack and a TCB.  tick_ms is
176	 * how long since the previous step.
177	 */
178	
179	void bk7258_status_led_step(uint32_t tick_ms)
180	{
181	  static uint32_t elapsed;
182	  enum led_phase_e p = s_phase;
183	  uint32_t slow = (elapsed / BLINK_SLOW_MS) & 1u;
184	  uint32_t fast = (elapsed / BLINK_FAST_MS) & 1u;
185	  bool green = false;
186	  bool red = false;
187	
188	  elapsed += tick_ms;
189	
190	  switch (p)
191	    {
192	      case PHASE_IDLE:
193	        green = true;
194	        break;
195	      case PHASE_WORKING:
196	        green = slow != 0;
197	        break;
198	      case PHASE_APPROVAL:
199	        red = true;
200	        break;
201	      case PHASE_DONE:
202	        /* Blink, not solid: under the new scheme solid green means idle, so
203	         * a solid DONE would vanish into it.  Fast blink for the hold, then
204	         * settle back.
205	         */
206	
207	        green = fast != 0;
208	        if (s_phase_left_ms > tick_ms)
209	          {
210	            s_phase_left_ms -= tick_ms;
211	          }
212	        else
213	          {
214	            led_phase_enter(PHASE_IDLE);
215	          }
216	        break;
217	      case PHASE_ERROR:
218	        red = slow != 0;
219	        break;
220	    }
221	
222	  led_write(LED_GREEN_PIN, green);
223	  led_write(LED_RED_PIN, red);
224	}
225	
226	int bk7258_status_led_initialize(void)
227	{
228	  bk7258_gpio_config_output(LED_RED_PIN, false);
229	  bk7258_gpio_config_output(LED_GREEN_PIN, false);
230	  remote_ctrl_register_observer(&g_led_observer);
231	  return 0;
232	}
