61	/* Exceptions 15 and up (SysTick and every peripheral IRQ) enter through
62	 * exception_direct (arm_vectors.c, bk7258_smp.c _vectors_core1), which does
63	 * not save the interrupted context into xcp.regs.  A panic raised there --
64	 * the RPTUN peer-panic kick from the other core is one -- made the NuttX
65	 * dump read a stale saved SP, and the unwinder walked off the task stack
66	 * into a precise BusFault on both cores.  Rebuild the interrupted context
67	 * from the hardware frame on PSP (r0-r3, r12, lr, pc, xpsr lead both the
68	 * basic and the FP extended frame) into a private buffer.  Nothing is
69	 * scheduled after a panic, so repointing xcp.regs only affects the dump. */
70	
71	#define BK7258_EXC_DIRECT_FIRST 15
72	
73	static void bk7258_panic_fix_irq_regs(void)
74	{
75	  static uint32_t regs[XCPTCONTEXT_REGS];
76	  FAR struct tcb_s *rtcb;
77	  FAR uint32_t *frame;
78	  uintptr_t base;
79	  uintptr_t top;
80	  uint32_t psp;
81	
82	  if (!up_interrupt_context() || getipsr() < BK7258_EXC_DIRECT_FIRST)
83	    {
84	      return;
85	    }
86	
87	  rtcb = running_task();
88	  base = (uintptr_t)rtcb->stack_base_ptr;
89	  top = base + rtcb->adj_stack_size;
90	
91	  __asm__ volatile ("mrs %0, psp" : "=r"(psp));
92	
93	  memset(regs, 0, sizeof(regs));
94	  if (psp >= base && psp + 8 * sizeof(uint32_t) <= top)
95	    {
96	      frame = (FAR uint32_t *)(uintptr_t)psp;
97	      regs[REG_R0]   = frame[0];
98	      regs[REG_R1]   = frame[1];
99	      regs[REG_R2]   = frame[2];
100	      regs[REG_R3]   = frame[3];
101	      regs[REG_R12]  = frame[4];
102	      regs[REG_LR]   = frame[5];
103	      regs[REG_PC]   = frame[6];
104	      regs[REG_XPSR] = frame[7];
105	
106	      /* The walk starts at the frame, so the interrupted PC/LR are in it. */
107	
108	      regs[REG_SP] = psp;
109	    }
110	  else
111	    {
112	      /* PSP is not on this task's stack: start at the top, scan nothing. */
113	
114	      regs[REG_SP] = top;
115	    }
116	
117	  rtcb->xcp.regs = regs;
118	}
