120	/* With BOARD_RESET_ON_ASSERT an AP panic ends in its own board_reset(),
121	 * i.e. SYSRESETREQ of CPU1 alone, unless the CP was flagged to reset the
122	 * whole chip.  CPU1 restarting under a running CP races the CP's RPTUN
123	 * rebuild (rpmsg_virtio.c:900 assert), so require the peer flag. */
124	
125	#if defined(CONFIG_BK7258_COMPONENT_AP) && \
126	    defined(CONFIG_BOARD_RESET_ON_ASSERT) && \
127	    CONFIG_BOARD_RESET_ON_ASSERT >= 1 && \
128	    !defined(CONFIG_BK7258_RPTUN_PANIC_PEER)
129	#  error "AP BOARD_RESET_ON_ASSERT needs BK7258_RPTUN_PANIC_PEER"
130	#endif
