141	
142	static int bk7258_cp_panic_notify(struct notifier_block *block,
143	                                  unsigned long action, void *data)
144	{
145	  (void)block;
146	  (void)data;
147	
148	  if (action == PANIC_KERNEL)
149	    {
150	      bk7258_panic_fix_irq_regs();
151	
152	#ifdef CONFIG_BK7258_WIFI_ARMINO_BASELINE
153	      /* Armino starts its interrupt watchdog (CONFIG_INT_WDT_PERIOD_MS,
154	       * 8 s) and AON watchdog (10 s) and feeds them from the tick, which a
155	       * panic stops.  If the board halts after the dump
156	       * (BOARD_RESET_ON_ASSERT == 0), stop both so the dump stays on the
157	       * console.  If it resets (>= 1), feed both once instead: the two
158	       * dumps take about 2 s, and a dump that hangs is still reset. */
159	
160	#  if defined(CONFIG_BOARD_RESET_ON_ASSERT) && \
161	      CONFIG_BOARD_RESET_ON_ASSERT >= 1
162	      bk_wdt_feed();
163	      bk_aon_wdt_feed();
164	#  else
165	      bk_wdt_stop();
166	      bk_aon_wdt_stop();
167	#  endif
168	#endif
169	    }
170	
171	  return 0;
172	}
173	
