279	void board_late_initialize(void)
280	{
281	  /* UART console registration is chip-owned. Board peripherals are added
282	   * only after their pinmux and hardware contracts are verified. */
283	
284	  /* Diagnostic-only boot ladder. /dev/console has been registered by the
285	   * time board_late_initialize runs; up_putc remains independent of syslog.
286	   */
287	  up_putc('K');
288	
289	  /* The hardware TRNG.  /dev/urandom is registered by devurandom_register()
290	   * (chips/bk7258/bk7258_trng.c) from nuttx's drivers_initialize(), under
291	   * CONFIG_DEV_URANDOM_ARCH — earlier than this point.  What is left here is
292	   * the Armino-facing half: bk_rand()/bk_fill_rand() and the bk_cli tools
293	   * expect bk_trng_driver_init() to have run before they use start/stop.
294	   */
295	
296	  bk_trng_driver_init();
297	
298	  /* Root CA for the ai_agent's TLS: pulls in chips/bk7258/bk7258_ca.c. */
299	  bk7258_ca_init();
300	
301	#ifdef CONFIG_BK7258_COMPONENT_CP
302	#ifdef CONFIG_BK7258_TIMER0
303	  {
304	    int timer_ret = bk7258_timer_initialize();
305	    if (timer_ret < 0)
306	      {
307	        syslog(LOG_ERR, "[BK7258] Timer0 lower-half init failed: %d\n",
308	               timer_ret);
309	      }
310	    else
311	      {
312	        syslog(LOG_INFO, "[BK7258] Timer0 lower-half registered\n");
313	      }
314	
315	    up_putc('L');
316	  }
317	#endif
318	  panic_notifier_chain_register(&g_bk7258_cp_panic_notifier);
319	#ifdef CONFIG_RPTUN
320	  int ret = bk7258_rptun_initialize();
321	  if (ret < 0)
322	    {
323	      syslog(LOG_ERR, "[AMP] CP RPTUN init failed: %d\n", ret);
324	    }
325	  else
326	    {
327	      syslog(LOG_INFO, "[AMP] CP RPTUN master initialized (Mailbox IRQ)\n");
328	#ifdef CONFIG_BK7258_MB_IPC_RPMSG
329	      ret = bk7258_mb_ipc_initialize();
330	      if (ret != 0)
331	        {
332	          syslog(LOG_ERR, "[AMP] CP mailbox IPC init failed: %d\n", ret);
333	        }
334	#endif
335	      /* AP-side apps drive Wi-Fi through here (scan / connect /
336	       * disconnect) rather than over usrsock.
337	       */
338	      ret = wlan_ctrl_server_init();
339	      if (ret != 0)
340	        {
341	          syslog(LOG_ERR, "[WLAN-CTRL] init failed: %d\n", ret);
342	        }
343	    }
