353	  (void)bk7258_armino_start();
354	#endif
355	#else
356	  bk7258_ap_initialize();
357	#endif
358	}
359	
360	int board_app_initialize(uintptr_t arg)
361	{
362	  static bool initialized;
363	
364	  /* The CP init task runs this before handing the console to the AP, and
365	   * nsh_main runs it again (CONFIG_NSH_ARCHINIT) when cu exits. */
366	
367	  if (initialized)
368	    {
369	      return 0;
370	    }
371	
372	  initialized = true;
373	
374	#ifdef CONFIG_FS_PROCFS
375	  /* nshlib does not mount procfs by itself, and neither component has a startup
376	   * script (CONFIG_NSH_ROMFSETC is unset for both): mount it here so `ps` and
377	   * the per-task affinity view work in the RPMsg-backed AP NSH.
378	   *
379	   * No longer restricted to the AP.  On the CP this is what makes `ifconfig`
380	   * usable at all: nsh_netcmds.c reads /proc/net to enumerate devices (:373)
381	   * and per-device state (:189), so without the mount the command exists but
382	   * fails with "is procfs mounted?".  That is also why
383	   * NSH_DISABLE_IFCONFIG/IFUPDOWN default to y when FS_PROCFS is off -- the
384	   * commands are useless without it. */
385	
386	  /* The pseudo-fs root accepts directories but not regular files
387	   * (CONFIG_PSEUDOFS_FILE is off), so /tmp has to be a real filesystem
388	   * before anything can create a file in it.  Without this every
389	   * open(..., O_CREAT) under /tmp fails with ENOENT and looks like the
390	   * directory is missing.
391	   */
392	
393	  if (mount("tmpfs", "/tmp", "tmpfs", 0, NULL) < 0)
394	    {
395	      syslog(LOG_ERR, "[BK7258] tmpfs mount failed: %d\n", get_errno());
396	    }
397	
398	  if (mount(NULL, CONFIG_NSH_PROC_MOUNTPOINT, "procfs", 0, NULL) < 0 &&
399	      get_errno() != EEXIST)
400	    {
401	      syslog(LOG_ERR, "[BK7258] procfs mount failed: %d\n", get_errno());
402	    }
403	#endif
