481	/* Copy the panic essentials into SWAP for the CP monitor: the AP console is
482	 * an RPMsg UART and cannot carry NuttX's own dump once interrupts are off. */
483	
484	static void bk7258_ap_panic_capture(FAR struct panic_notifier_s *info)
485	{
486	  static bool captured;
487	  struct bk7258_ap_panic_s panic;
488	  FAR uint32_t *regs;
489	  size_t len;
490	
491	  if (captured || info == NULL)
492	    {
493	      return;
494	    }
495	
496	  captured = true;
497	  memset(&panic, 0, sizeof(panic));
498	  panic.linenum = (uint32_t)info->linenum;
499	
500	  /* Keep the tail of a long path: the file name is the useful part. */
501	
502	  if (info->filename != NULL)
503	    {
504	      len = strlen(info->filename);
505	      strlcpy(panic.filename,
506	              len >= sizeof(panic.filename) ?
507	              info->filename + len - (sizeof(panic.filename) - 1) :
508	              info->filename,
509	              sizeof(panic.filename));
510	    }
511	
512	  if (info->msg != NULL)
513	    {
514	      strlcpy(panic.msg, info->msg, sizeof(panic.msg));
515	    }
516	
517	#if CONFIG_TASK_NAME_SIZE > 0
518	  if (info->rtcb != NULL)
519	    {
520	      strlcpy(panic.task, info->rtcb->name, sizeof(panic.task));
521	    }
522	#endif
523	
524	  regs = info->regs;
525	  if (regs != NULL)
526	    {
527	      panic.pc = regs[REG_PC];
528	      panic.lr = regs[REG_LR];
529	      panic.sp = regs[REG_SP];
530	    }
531	
532	  /* Publish before unwinding: a fault inside up_backtrace() must not cost
533	   * the location that is already known. */
534	
535	  bk7258_ap_panic_write(&panic);
536	
537	  /* Inside an interrupt (the RPTUN peer-panic kick from the CP) the unwinder
538	   * took a precise BusFault on the board; keep the record without frames. */
539	
540	  if (up_interrupt_context())
541	    {
542	      return;
543	    }
544	
545	#ifdef CONFIG_ARCH_HAVE_BACKTRACE
546	  {
547	    FAR void *bt[BK7258_AP_PANIC_NBT];
548	    int n = up_backtrace(info->rtcb, bt, BK7258_AP_PANIC_NBT, 0);
549	    int i;
550	
551	    for (i = 0; i < n && i < BK7258_AP_PANIC_NBT; i++)
552	      {
553	        panic.bt[i] = (uint32_t)(uintptr_t)bt[i];
554	      }
555	
556	    panic.nbt = i;
557	    bk7258_ap_panic_write(&panic);
558	  }
559	#endif
560	}
