572	static ssize_t bk7258_ap_panic_puts(FAR syslog_channel_t *channel,
573	                                    FAR const char *buf, size_t len)
574	{
575	  size_t i;
576	
577	  (void)channel;
578	  for (i = 0; i < len; i++)
579	    {
