586	static const struct syslog_channel_ops_s g_bk7258_ap_panic_ops =
587	{
588	  bk7258_ap_panic_putc,
589	  bk7258_ap_panic_putc,
590	  NULL,
591	  bk7258_ap_panic_puts,
592	  bk7258_ap_panic_puts,
