597	{
598	  .sc_ops = &g_bk7258_ap_panic_ops,
599	};
600	
601	static int bk7258_ap_panic_notify(struct notifier_block *block,
602	                                  unsigned long action, void *data)
603	{
604	  FAR struct panic_notifier_s *info = data;
605	  uint32_t fault;
606	
607	  (void)block;
608	
609	  /* PANIC_TASK can describe a task-local assertion. Only kernel panic stages
610	   * are fatal evidence for this AP instance. */
611	
612	  if (action == PANIC_KERNEL_FINAL)
613	    {
614	      /* The dump is out.  Hand UART0 back before _assert() runs the reboot
615	       * notifier chain, where RPTUN (RPTUN_AUTO_RESET_IN_REBOOT_NOTIFIER)
616	       * wakes the CP to dump its own state. */
617	
618	      /* An interrupt-context dump goes through SYSLOG_INTBUFFER; drain its
619	       * tail to UART0 while the token is still ours. */
620	
621	      syslog_flush();
622	      bk7258_ap_uart_token_release();
623	      return 0;
624	    }
625	
626	  if (action != PANIC_TASK)
627	    {
628	      bk7258_panic_fix_irq_regs();
629	
630	      /* Mute the CP and route the coming NuttX dump to UART0.  The single
631	       * syslog slot is replaced, not shared (SYSLOG_MAX_CHANNELS=1). */
632	
633	      bk7258_ap_uart_token_take();
634	      syslog_channel_register(&g_bk7258_ap_panic_channel);
635	
636	      /* Before the FAULT stage, so the CP never sees a fault without it. */
637	
638	      bk7258_ap_panic_capture(info);
639	
640	      /* Encode the assertion location into the fault word so the CP-side
641	       * monitor can point at the failing source: high byte = a short hash of
642	       * the filename, low byte = line number. */
643	
644	      if (info != NULL && info->filename != NULL)
645	        {
646	          uint32_t hash = 0;
647	          FAR const char *p;
648	
649	          for (p = info->filename; *p != '\0'; p++)
650	            {
651	              hash = (hash << 1) ^ (hash >> 31) ^ (uint32_t)*p;
652	            }
653	
654	          fault = BK7258_AP_FAULT_PANIC_BASE |
655	                  ((hash & UINT32_C(0xff)) << 8) |
656	                  ((uint32_t)(info->linenum & UINT32_C(0xff)));
657	        }
658	      else
659	        {
660	          fault = BK7258_AP_FAULT_PANIC_BASE |
661	                  ((uint32_t)action & UINT32_C(0xff));
662	        }
663	
664	      bk7258_ap_record_fault(fault);
665	    }
666	
667	  return 0;
668	}
669	
670	static struct notifier_block g_bk7258_ap_panic_notifier =
671	{
672	  .notifier_call = bk7258_ap_panic_notify,
673	  .priority = 100,
674	};
