677	static int bk7258_ap_amp_initialize(int argc, char *argv[])
678	{
679	  int ret;
680	
681	  (void)argc;
682	  (void)argv;
683	
684	  ret = bk7258_rptun_initialize();
685	  if (ret < 0)
686	    {
687	      /* Keep the heartbeat task alive so the SWAP record still proves AP
688	       * liveness even when AMP initialization fails.
689	       */
690	
691	      return ret;
692	    }
693	
694	#ifdef CONFIG_BK7258_MB_IPC_RPMSG
695	  ret = bk7258_mb_ipc_initialize();
696	  if (ret != 0)
697	    {
698	      return ret;
699	    }
700	#endif
701	
702	  /* No rpmsg netdev registration here: the NET_RPMSG_DRV client/server
703	   * pair deadlocks on this platform (the AP's rpmsg_create_ept sends an
704	   * NS announcement and waits synchronously; the CP's ns_bind handler
705	   * answers it by creating the peer endpoint, whose own announcement
706	   * waits for an ACK the blocked AP will never send).  Cross-core
707	   * networking goes through the Vela-standard NET_RPMSG socket domain
708	   * instead; the transport this kthread initialized above is shared. */
709	
710	  /* Publish scheduler-running only after the AP-side RPTUN/RPMsg instance is
711	   * initialized.  CP uses the SWAP generation transition as the trigger to
712	   * tear down and rebuild its stale remote transport, so advertising this
713	   * stage earlier would let CP restart AP while its new RPTUN instance was
714	   * still coming up. */
715	
716	  bk7258_ap_record_mark_scheduler();
717	
718	  return 0;
719	}
720	#endif
