722	static int bk7258_ap_health_thread(int argc, char *argv[])
723	{
724	  bool led_on = true;
725	  int ret;
726	
727	  (void)argc;
728	  (void)argv;
729	
730	  for (; ; )
731	    {
732	      ret = nxsig_usleep(1000 * 1000);
733	      if (ret < 0)
734	        {
735	          bk7258_ap_record_fault(BK7258_AP_FAULT_SLEEP_BASE |
736	                                 ((uint32_t)-ret & UINT32_C(0xff)));
737	          bk7258_ap_heartbeat_led_write(false);
738	          return ret;
739	        }
740	
741	      led_on = !led_on;
742	      bk7258_ap_heartbeat_led_write(led_on);
743	      bk7258_ap_record_heartbeat();
744	    }
745	
746	  return 0;
747	}
