749	static void bk7258_ap_initialize(void)
750	{
751	  int ret;
752	
753	  /* board_late_initialize() runs before nsh_main. Keep board health and AMP
754	   * setup in kernel workers so the standard NSH entry can own /dev/console.
755	   * The notifier is registered here, after tasklist_initialize(): earlier
756	   * registration would dereference a NULL TCB inside sched_lock().
757	   */
758	
759	  syslog(LOG_INFO, "BK7258: bk7258_ap_initialize called\n");
760	
761	  panic_notifier_chain_register(&g_bk7258_ap_panic_notifier);
762	  bk7258_ap_heartbeat_led_initialize();
763	  bk7258_ap_heartbeat_led_write(true);
764	
765	  /* Initialize audio devices first (before RPTUN which may return early) */
766	
767	#ifdef CONFIG_AUDIO_BK7258
768	  syslog(LOG_INFO, "BK7258: Initializing audio devices...\n");
769	
770	  /* Register the DevKit PA control ops before the playback device is
771	   * created so the driver never runs with an unknown PA state.
772	   */
773	
774	  ret = bk7258_devkit_audio_pa_register();
775	  if (ret < 0)
776	    {
777	      syslog(LOG_ERR, "BK7258 PA registration failed: %d; "
778	                      "playback device disabled\n", ret);
779	    }
780	  else
781	    {
782	      ret = bk7258_audio_playback_initialize();
783	      if (ret < 0)
784	        {
785	          syslog(LOG_ERR, "BK7258 playback audio init failed: %d\n", ret);
786	        }
787	      else
788	        {
789	          syslog(LOG_INFO, "BK7258: Playback device registered OK\n");
790	        }
791	    }
792	
793	#ifdef CONFIG_AUDIO_BK7258_CAPTURE
794	  ret = bk7258_audio_capture_initialize();
795	  if (ret < 0)
796	    {
797	      syslog(LOG_ERR, "BK7258 capture audio init failed: %d\n", ret);
798	    }
799	  else
800	    {
801	      syslog(LOG_INFO, "BK7258: Capture device registered OK\n");
802	    }
803	#endif
804	#endif
805	
806	  /* Initialize buttons (non-fatal if it fails) */
807	
808	#ifdef CONFIG_INPUT_BUTTONS_LOWER
809	  ret = btn_lower_initialize("/dev/btn0");
810	  if (ret == 0)
811	    {
812	      /* LED first: the key thread steps it, so the pins must be configured
813	       * before that thread exists.
814	       */
815	
816	      bk7258_status_led_initialize();
817	      bk7258_buttons_input_initialize();
818	    }
819	  if (ret < 0)
820	    {
821	      syslog(LOG_ERR, "BK7258 button init failed: %d\n", ret);
822	    }
823	  else
824	    {
825	      syslog(LOG_INFO, "BK7258: /dev/btn0 registered OK\n");
826	    }
827	#endif
828	
829	#ifdef CONFIG_RPTUN
830	  ret = kthread_create("bk7258-amp-init", 95, 8192,
831	                       bk7258_ap_amp_initialize, NULL);
832	  if (ret < 0)
833	    {
834	      bk7258_ap_record_fault(UINT32_C(0x52505400) |
835	                             ((uint32_t)-ret & UINT32_C(0xff)));
836	      bk7258_ap_heartbeat_led_write(false);
837	    }
838	#endif
839	
840	  /* The heartbeat is the only thing the CP's stall detector sees, so it
841	   * must not starve behind application threads.  At 80 it sat below
842	   * ai_agent's LVGL loop and lvgldemo (100), and a busy render loop alone
843	   * produced "[AP] stalled".  200 stays below rpmsg (224) and AppBringUp
844	   * (240); the loop only sleeps 1 s, toggles the LED and bumps a counter,
845	   * so a stall now means the AP really stopped scheduling.
846	   */
847	
848	  ret = kthread_create("bk7258-ap-health", 200, 2048,
849	                       bk7258_ap_health_thread, NULL);
850	  if (ret < 0)
851	    {
852	      bk7258_ap_record_fault(UINT32_C(0x48425400) |
853	                             ((uint32_t)-ret & UINT32_C(0xff)));
854	      bk7258_ap_heartbeat_led_write(false);
855	    }
856	}
857	#endif
