115	/* UART0 panic token, SWAP word 50.  UART0 belongs to the CP; the AP has no
116	 * console UART.  An AP panic takes the token and writes the FIFO directly
117	 * (its RPMsg console is dead with interrupts off), and the CP drops its own
118	 * output while the token is held so the two never interleave.  The AP
119	 * releases it at PANIC_KERNEL_FINAL, before RPTUN wakes the CP; the CP clears
120	 * it at boot, in bk7258_ap_record_prepare(), and after a timeout. */
121	
122	#define BK7258_AP_SWAP_UART_WORD  UINT32_C(50)
123	#define BK7258_AP_UART_MAGIC      UINT32_C(0x41505554) /* "APUT" */
124	
