81	static inline uint32_t bk7258_ap_reg_read(uintptr_t address)
82	{
83	  return *(volatile uint32_t *)address;
84	}
85	
86	static inline void bk7258_ap_reg_write(uintptr_t address, uint32_t value)
87	{
88	  *(volatile uint32_t *)address = value;
89	}
90	
91	static inline void bk7258_ap_lifecycle_barrier(void)
92	{
93	  __asm__ volatile ("dsb\n\tisb" : : : "memory");
94	}
