96	struct bk7258_ap_audio_wake_s
97	{
98	  uint32_t power_before;
99	  uint32_t power_after;
100	  uint32_t mem_ctrl1_before;
101	  uint32_t mem_ctrl1_after;
102	  uint32_t mem_ctrl2_before;
103	  uint32_t mem_ctrl2_after;
104	};
105	
106	/* CP owns these shared SYS controls while CPU1 is held in reset.  Keep the
107	 * three whole-word RMW operations in that exclusive window, then verify the
108	 * hardware-visible values before AP can execute any audio initialization.
109	 */
110	
111	static int bk7258_ap_audio_wake(
112	  struct bk7258_ap_audio_wake_s *state)
113	{
114	  state->power_before =
115	    bk7258_ap_reg_read(BK7258_SYS_POWER_WAKEUP);
116	  state->mem_ctrl1_before =
117	    bk7258_ap_reg_read(BK7258_SYS_DEV_MEM_CTRL1);
118	  state->mem_ctrl2_before =
119	    bk7258_ap_reg_read(BK7258_SYS_DEV_MEM_CTRL2);
120	
121	  bk7258_ap_reg_write(BK7258_SYS_POWER_WAKEUP,
122	                      state->power_before &
123	                      ~BK7258_SYS_AUDP_POWER_DOWN);
124	  bk7258_ap_reg_write(BK7258_SYS_DEV_MEM_CTRL1,
125	                      state->mem_ctrl1_before &
126	                      ~BK7258_SYS_AUD_MEM_LOW_POWER);
127	  bk7258_ap_reg_write(BK7258_SYS_DEV_MEM_CTRL2,
128	                      state->mem_ctrl2_before &
129	                      ~BK7258_SYS_AUD_MEM_LOW_POWER);
130	  bk7258_ap_lifecycle_barrier();
131	  up_udelay(10);
132	
133	  state->power_after =
134	    bk7258_ap_reg_read(BK7258_SYS_POWER_WAKEUP);
135	  state->mem_ctrl1_after =
136	    bk7258_ap_reg_read(BK7258_SYS_DEV_MEM_CTRL1);
137	  state->mem_ctrl2_after =
138	    bk7258_ap_reg_read(BK7258_SYS_DEV_MEM_CTRL2);
139	
140	  if ((state->power_after & BK7258_SYS_AUDP_POWER_DOWN) != 0 ||
141	      (state->mem_ctrl1_after & BK7258_SYS_AUD_MEM_LOW_POWER) != 0 ||
142	      (state->mem_ctrl2_after & BK7258_SYS_AUD_MEM_LOW_POWER) != 0)
143	    {
144	      return -EIO;
145	    }
146	
147	  return 0;
148	}
