208	int board_start_cpu(int cpuid)
209	{
210	  struct bk7258_ap_audio_wake_s audio_wake = {0};
211	  struct bk7258_ap_boot_record_s record;
212	  irqstate_t flags;
213	  uint32_t control;
214	  uint32_t expected;
215	  uint32_t initial_msp;
216	  uint32_t reset_pc;
217	  uint32_t status;
218	  const volatile struct bk7258_ap_image_contract_s *image_contract;
219	  uint32_t boot_sequence = 0;
220	  unsigned int count;
221	  bool audio_wake_attempted = false;
222	  bool released = false;
223	  int audio_wake_ret = 0;
224	  int ret;
225	
226	  if (cpuid != 1)
227	    {
228	      return -EINVAL;
229	    }
230	
231	  ret = nxmutex_lock(&g_ap_start_lock);
232	  if (ret < 0)
233	    {
234	      return ret;
235	    }
236	
237	  if (g_ap_started)
238	    {
239	      ret = -EBUSY;
240	      goto out_unlock;
241	    }
242	
243	  /* Fail closed before trusting any AP partition bytes. This also makes the
244	   * default placeholder/recovery package safe if a prior stage left CPU1
245	   * running: CPU1 is parked before OVAP identity or vector validation. */
246	
247	  ret = bk7258_ap_force_reset();
248	  if (ret < 0)
249	    {
250	      syslog(LOG_ERR, "[AP] start: force_reset failed ret=%d\n", ret);
251	      goto out_unlock;
252	    }
253	
254	  image_contract =
255	    (const volatile struct bk7258_ap_image_contract_s *)
256	      (BK7258_AP_XIP_VECTOR_BASE + BK7258_AP_IMAGE_CONTRACT_OFFSET);
257	  syslog(LOG_INFO,
258	         "[AP] start: contract@%p magic=%08lx abi=%lu build=%08lx "
259	         "vbase=%08lx (want magic=%08lx vbase=%08lx)\n",
260	         (const void *)image_contract,
261	         (unsigned long)image_contract->magic,
262	         (unsigned long)image_contract->abi_version,
263	         (unsigned long)image_contract->build_id,
264	         (unsigned long)image_contract->vector_base,
265	         (unsigned long)BK7258_AP_IMAGE_MAGIC,
266	         (unsigned long)BK7258_AP_XIP_VECTOR_BASE);
267	  if (image_contract->magic != BK7258_AP_IMAGE_MAGIC ||
268	      image_contract->abi_version != BK7258_AP_BOOT_ABI_VERSION ||
269	      image_contract->build_id != BK7258_AP_BUILD_ID ||
270	      image_contract->vector_base != BK7258_AP_XIP_VECTOR_BASE)
271	    {
272	      syslog(LOG_ERR, "[AP] start: contract mismatch -> ENOEXEC\n");
273	      ret = -ENOEXEC;
274	      goto out_unlock;
275	    }
276	
277	  initial_msp = bk7258_ap_reg_read(BK7258_AP_XIP_VECTOR_BASE);
278	  reset_pc = bk7258_ap_reg_read(BK7258_AP_XIP_VECTOR_BASE + sizeof(uint32_t));
279	  syslog(LOG_INFO,
280	         "[AP] start: vbase=%08lx msp=%08lx reset_pc=%08lx "
281	         "(ram=[%08lx..%08lx] xip_end=%08lx)\n",
282	         (unsigned long)BK7258_AP_XIP_VECTOR_BASE,
283	         (unsigned long)initial_msp, (unsigned long)reset_pc,
284	         (unsigned long)BK7258_AP_RAM_BASE, (unsigned long)BK7258_AP_RAM_END,
285	         (unsigned long)(BK7258_AP_XIP_VECTOR_BASE + BK7258_AP_XIP_SIZE));
286	  if (initial_msp <= BK7258_AP_RAM_BASE ||
287	      initial_msp > BK7258_AP_RAM_END ||
288	      (initial_msp & 7) != 0 ||
289	      (reset_pc & 1) == 0 ||
290	      (reset_pc & ~UINT32_C(1)) < BK7258_AP_XIP_VECTOR_BASE ||
291	      (reset_pc & ~UINT32_C(1)) >=
292	        BK7258_AP_XIP_VECTOR_BASE + BK7258_AP_XIP_SIZE)
293	    {
294	      syslog(LOG_ERR, "[AP] start: vector bounds check failed -> ENOEXEC\n");
295	      ret = -ENOEXEC;
296	      goto out_unlock;
297	    }
298	
299	  /* Power the CPU1 domain up through the authority sequence before releasing
300	   * the core, the way upstream does it (startup_cpu1.c:261 votes
301	   * PM_POWER_MODULE_NAME_CPU1 ON ahead of the release).
302	   *
303	   * This step was missing, and it only started to matter once
304	   * sys_hal_low_power_hardware_init() moved to __start() (bk7258_start.c) to
305	   * match the authority's boot position.  That function powers CPU1 and CPU2
306	   * OFF -- upstream a no-op, because neither core has been started yet -- so
307	   * the AP release below now runs against a halted, powered-down core.  Board
308	   * evidence (/tmp/0910-vela-11.log):
309	   *
310	   *   [AP] start: cpu1_ctrl before=0000001a          POWER_DOWN|HALT|bit4
311	   *   [AP] start: cpu1_ctrl readback=00000038 expected=00000020 -> EIO
312	   *   [AP] CPU1 release failed: -1 errno=5
313	   *
314	   * POWER_DOWN (bit1) does clear and stay clear; HALT (bit3) and bit4 read
315	   * back set.  That is a settling problem rather than a missing write: the
316	   * authority clears power and halt in two separate register writes and then
317	   * spins 1000 iterations, with the comment "wait halt really cleared, clock
318	   * support finish" (sys_hal.c:150-157), whereas the sequence below clears both
319	   * in one write and reads back after a barrier.  Our own settling loop
320	   * (BK7258_AP_POWER_STABILIZE_LOOPS) sits AFTER that read-back check, so the
321	   * check lands inside the window the hardware needs.
322	   *
323	   * Same register on both sides -- ours is BK7258_SYS_BASE + 0x014, the
324	   * authority's sys_cpu1_int_halt_clk_op is SOC_SYS_REG_BASE + (0x5 << 2)
325	   * (sys_ll.h:292); both resolve to 0x44010014.
326	   *
327	   * Called before up_irq_save() on purpose: the authority sequence contains a
328	   * busy-wait, and there is no reason to hold interrupts off across it.
329	   * Nothing else in this image touches the CPU1 power domain, so the state
330	   * cannot change between here and the release below.
331	   *
332	   * sys_hal_module_power_ctrl() rather than bk_pm_module_vote_power_ctrl() for
333	   * the same reason as the PSRAM domain in bk7258_psram.c: the vote function in
334	   * this port (hal_port/platform_shim.c:188) has no CPU1 branch and would answer
335	   * BK_ERR_NOT_SUPPORT, and it is built only under CONFIG_BK7258_WIFI.  The HAL
336	   * entry is authority code under pm/ and compiles unconditionally.  When
337	   * platform_shim's vote layer is replaced by the authority's pm.c this becomes
338	   * the CPU1 vote and this call site is the only line that changes.
339	   *
340	   * Declared locally to keep the PM module's SoC headers out of board code. */
341	
342	  {
343	    extern void sys_hal_module_power_ctrl(int module, int power_state);
344	
345	    /* POWER_MODULE_NAME_CPU1 == 17, CPU2 == 19, POWER_MODULE_STATE_ON == 0
346	     * (aon_pmu/.../sys_types.h:337,339 and :417). */
347	
348	    sys_hal_module_power_ctrl(17 /* CPU1 */, 0 /* STATE_ON */);
349	
350	    /* CPU2 too, because sys_hal_power_config_default() switched off both slave
351	     * cores and the authority restores both before starting either
352	     * (cli_main.c:509-516 votes CPU1 ON, start_cpu1_core(), CPU2 ON,
353	     * start_cpu2_core()).
354	     *
355	     * Done from here rather than next to the CPU2 release in
356	     * chips/bk7258/bk7258_smp.c because that file belongs to the AP image,
357	     * which does not link sys_hal_module_power_ctrl at all -- the PM module is
358	     * CP-only (verified with nm: ap/nuttx has up_cpu_start and
359	     * bk7258_smp_initialize, cp/nuttx has sys_hal_module_power_ctrl).  CP is
360	     * also the core that switched the domain off, so restoring it here keeps
361	     * the whole slave-core power lifecycle on one side.
362	     *
363	     * Not what fixed the CPU2 release: the fault record showed bit1 POWER_DOWN
364	     * already clear (fault=0x43325438, low byte 0x38 = HALT|speed|RXEVT_SEL),
365	     * so bk7258_smp.c's own direct write was landing.  This is authority
366	     * symmetry, not the repair -- dropping HALT from
367	     * BK7258_CPU2_CTRL_LIFECYCLE_MASK is. */
368	
369	    sys_hal_module_power_ctrl(19 /* CPU2 */, 0 /* STATE_ON */);
370	  }
371	
372	  flags = up_irq_save();
373	
374	  /* Follow Armino's BK7258 lifecycle order. CPU_CURRENT_RUN_STATUS is
375	   * diagnostic only; its transient values are not a launch precondition. */
376	
377	  control = bk7258_ap_reg_read(BK7258_SYS_CPU1_CTRL);
378	  syslog(LOG_INFO, "[AP] start: cpu1_ctrl before=%08lx\n",
379	         (unsigned long)control);
380	  control &= ~(BK7258_SYS_CPU1_RESET_RELEASE |
381	               BK7258_SYS_CPU1_POWER_DOWN |
382	               BK7258_SYS_CPU1_HALT |
383	               BK7258_SYS_CPU1_OFFSET_MASK);
384	  control |= BK7258_SYS_CPU1_RXEVT_SEL;
385	  bk7258_ap_reg_write(BK7258_SYS_CPU1_CTRL, control);
386	  bk7258_ap_lifecycle_barrier();
387	  expected = control & BK7258_AP_CPU1_CTRL_LIFECYCLE_MASK;
388	  if ((bk7258_ap_reg_read(BK7258_SYS_CPU1_CTRL) &
389	       BK7258_AP_CPU1_CTRL_LIFECYCLE_MASK) != expected)
390	    {
391	      syslog(LOG_ERR,
392	             "[AP] start: cpu1_ctrl readback=%08lx expected=%08lx -> EIO\n",
393	             (unsigned long)bk7258_ap_reg_read(BK7258_SYS_CPU1_CTRL),
394	             (unsigned long)expected);
395	      up_irq_restore(flags);
396	      ret = -EIO;
397	      goto out_unlock;
398	    }
399	
400	  /* Keep the vendor power-domain settling window explicit and
401	   * non-optimizable. */
402	
403	  for (count = 0; count < BK7258_AP_POWER_STABILIZE_LOOPS; count++)
404	    {
405	      __asm__ volatile ("nop");
406	    }
407	
408	  for (count = 0; count < BK7258_AP_POWER_WAIT_LOOPS; count++)
409	    {
410	      /* HALTED_STATE dropped from the wait condition for the same reason it is
411	       * out of BK7258_AP_CPU1_CTRL_LIFECYCLE_MASK: the authority releases CPU1
412	       * from a state where halt is asserted and never waits for it to clear
413	       * (reset_cpu1_core(), system_main.c:175-183).  Keeping it here would only
414	       * move the failure from the -EIO above to the -ETIMEDOUT below.
415	       *
416	       * PWR_DW_STATE and RESET_STATE stay: pwr_dw is what the CPU1 power vote
417	       * ahead of this loop actually clears, and it was observed clearing on the
418	       * board, so both remain meaningful preconditions. */
419	
420	      status = bk7258_ap_reg_read(BK7258_SYS_CPU_STATUS);
421	      if ((status & (BK7258_SYS_CPU1_PWR_DW_STATE |
422	                     BK7258_SYS_CPU1_RESET_STATE)) == 0)
423	        {
424	          break;
425	        }
426	    }
427	
428	  if (count == BK7258_AP_POWER_WAIT_LOOPS)
429	    {
430	      syslog(LOG_ERR,
431	             "[AP] start: power-wait timeout cpu_status=%08lx -> ETIMEDOUT\n",
432	             (unsigned long)bk7258_ap_reg_read(BK7258_SYS_CPU_STATUS));
433	      up_irq_restore(flags);
434	      ret = -ETIMEDOUT;
435	      goto out_unlock;
436	    }
437	
438	  syslog(LOG_INFO, "[AP] start: cpu1 powered up, cpu_status=%08lx after %u\n",
439	         (unsigned long)bk7258_ap_reg_read(BK7258_SYS_CPU_STATUS),
440	         (unsigned int)count);
441	
442	  /* CPU1 is still held in reset and CP interrupts remain disabled, so this
443	   * is the exclusive ownership window for the shared audio power/SRAM RMWs.
444	   * A failed readback keeps AP in reset and prevents an unusable audio
445	   * subsystem from being published.
446	   */
447	
448	  audio_wake_attempted = true;
449	  audio_wake_ret = bk7258_ap_audio_wake(&audio_wake);
450	  if (audio_wake_ret < 0)
451	    {
452	      up_irq_restore(flags);
453	      ret = audio_wake_ret;
454	      goto out_unlock;
455	    }
456	
457	  /* CPU1 is now held in reset, so CP owns SWAP exclusively while it creates
458	   * the next boot sequence. This ordering also makes a future AP restart safe:
459	   * the old AP cannot race the new CP record with a final heartbeat write. */
460	
461	  boot_sequence = bk7258_ap_record_prepare();
462	
463	  control = bk7258_ap_reg_read(BK7258_SYS_CPU1_CTRL);
464	  control &= ~(BK7258_SYS_CPU1_OFFSET_MASK |
465	               BK7258_SYS_CPU1_RESET_RELEASE);
466	  /* The Armino setter takes address >> 8 as a bitfield value. This direct
467	   * register write must place that value back into bits [31:8]. */
468	
469	  control |= BK7258_SYS_CPU_BOOT_OFFSET(BK7258_AP_XIP_VECTOR_BASE);
470	  control |= BK7258_SYS_CPU1_RXEVT_SEL;
471	  bk7258_ap_reg_write(BK7258_SYS_CPU1_CTRL, control);
472	  bk7258_ap_lifecycle_barrier();
473	  expected = control & BK7258_AP_CPU1_CTRL_LIFECYCLE_MASK;
474	  if ((bk7258_ap_reg_read(BK7258_SYS_CPU1_CTRL) &
475	       BK7258_AP_CPU1_CTRL_LIFECYCLE_MASK) != expected)
476	    {
477	      syslog(LOG_ERR,
478	             "[AP] start: vec-offset readback=%08lx expected=%08lx -> EIO\n",
479	             (unsigned long)bk7258_ap_reg_read(BK7258_SYS_CPU1_CTRL),
480	             (unsigned long)expected);
481	      up_irq_restore(flags);
482	      ret = -EIO;
483	      goto out_unlock;
484	    }
485	
486	  syslog(LOG_INFO, "[AP] start: releasing CPU1 reset (seq=%u)\n",
487	         (unsigned int)boot_sequence);
488	  bk7258_ap_reg_write(BK7258_SYS_CPU1_CTRL,
489	                      control | BK7258_SYS_CPU1_RESET_RELEASE);
490	  released = true;
491	  bk7258_ap_lifecycle_barrier();
492	  expected = (control | BK7258_SYS_CPU1_RESET_RELEASE) &
493	             BK7258_AP_CPU1_CTRL_LIFECYCLE_MASK;
494	  if ((bk7258_ap_reg_read(BK7258_SYS_CPU1_CTRL) &
495	       BK7258_AP_CPU1_CTRL_LIFECYCLE_MASK) != expected)
496	    {
497	      syslog(LOG_ERR,
498	             "[AP] start: release readback=%08lx expected=%08lx -> EIO\n",
499	             (unsigned long)bk7258_ap_reg_read(BK7258_SYS_CPU1_CTRL),
500	             (unsigned long)expected);
501	      up_irq_restore(flags);
502	      ret = -EIO;
503	      goto out_rollback;
504	    }
505	
506	  for (count = 0; count < BK7258_AP_POWER_WAIT_LOOPS; count++)
507	    {
508	      status = bk7258_ap_reg_read(BK7258_SYS_CPU_STATUS);
509	      if ((status & BK7258_SYS_CPU1_RESET_STATE) != 0)
510	        {
511	          break;
512	        }
513	    }
514	
515	  if (count == BK7258_AP_POWER_WAIT_LOOPS)
516	    {
517	      syslog(LOG_ERR,
518	             "[AP] start: post-release reset-state timeout "
519	             "cpu_status=%08lx -> ETIMEDOUT\n",
520	             (unsigned long)bk7258_ap_reg_read(BK7258_SYS_CPU_STATUS));
521	      up_irq_restore(flags);
522	      ret = -ETIMEDOUT;
523	      goto out_rollback;
524	    }
525	
526	  up_irq_restore(flags);
527	
528	  /* Do not report a successful start merely because MMIO writes completed.
529	   * The current-sequence RESET_ENTERED record proves CPU1 fetched the AP
530	   * vector and executed team OpenVela startup code. */
531	
532	  for (count = 0; count < BK7258_AP_RESET_WAIT_ATTEMPTS; count++)
533	    {
534	      if (bk7258_ap_record_read(&record) &&
535	          record.boot_sequence == boot_sequence)
536	        {
537	          if (record.stage == BK7258_AP_STAGE_RESET_ENTERED ||
538	              record.stage == BK7258_AP_STAGE_SCHEDULER_RUNNING)
539	            {
540	              g_ap_boot_sequence = boot_sequence;
541	              g_ap_started = true;
542	              syslog(LOG_INFO,
543	                     "[AP] start: OK stage=%s seq=%u after %u\n",
544	                     bk7258_ap_stage_name(record.stage),
545	                     (unsigned int)boot_sequence,
546	                     (unsigned int)count);
547	              ret = 0;
548	              goto out_unlock;
549	            }
550	
551	          if (record.stage == BK7258_AP_STAGE_FAULT)
552	            {
553	              syslog(LOG_ERR,
554	                     "[AP] start fault seq=%u code=0x%08x\n",
555	                     (unsigned int)boot_sequence,
556	                     (unsigned int)record.fault);
557	              ret = -EFAULT;
558	              goto out_rollback;
559	            }
560	        }
561	
562	      nxsig_usleep(BK7258_AP_RESET_WAIT_USEC);
563	    }
564	
565	  syslog(LOG_ERR,
566	         "[AP] start: boot-record wait timeout seq=%u attempts=%u "
567	         "(last valid=%d seq=%u stage=%u) -> ETIMEDOUT\n",
568	         (unsigned int)boot_sequence,
569	         (unsigned int)BK7258_AP_RESET_WAIT_ATTEMPTS,
570	         (int)bk7258_ap_record_read(&record),
571	         (unsigned int)record.boot_sequence,
572	         (unsigned int)record.stage);
573	  ret = -ETIMEDOUT;
574	
575	out_rollback:
576	  if (released)
577	    {
578	      int reset_ret = bk7258_ap_force_reset();
579	      if (reset_ret < 0)
580	        {
581	          syslog(LOG_ERR, "[AP] rollback reset failed: %d\n", reset_ret);
582	        }
583	    }
584	
585	out_unlock:
586	  if (audio_wake_attempted)
587	    {
588	      syslog(audio_wake_ret < 0 ? LOG_ERR : LOG_INFO,
589	             "[AP] audio wake ret=%d pwr=%08lx->%08lx "
590	             "sd=%08lx->%08lx ds=%08lx->%08lx\n",
591	             audio_wake_ret,
592	             (unsigned long)audio_wake.power_before,
593	             (unsigned long)audio_wake.power_after,
594	             (unsigned long)audio_wake.mem_ctrl1_before,
595	             (unsigned long)audio_wake.mem_ctrl1_after,
596	             (unsigned long)audio_wake.mem_ctrl2_before,
597	             (unsigned long)audio_wake.mem_ctrl2_after);
598	    }
599	
600	  nxmutex_unlock(&g_ap_start_lock);
601	  return ret;
602	}
603	
604	static int bk7258_ap_recover_transport(void)
605	{
606	  unsigned int attempt;
607	  int ret;
608	
609	  if (g_ap_recovering)
610	    {
611	      return -EALREADY;
612	    }
613	
614	  g_ap_recovering = true;
615	  g_ap_started = false;
616	
617	  /* The generic RPTUN stop path destroys the remoteproc VirtIO device and
618	   * broadcasts RPMsg device-destroy callbacks before returning the transport
619	   * to OFFLINE.  Do this before board_start_cpu() resets AP again, otherwise
620	   * the old vrings and uart_rpmsg endpoint can survive into the new AP
621	   * generation. */
622	
623	  /* remoteproc_stop() rejects CONFIGURED/READY while the RPTUN worker is
624	   * still completing its start transaction.  AP can reboot exactly during
625	   * that window, so treat -EBUSY as a transient state and retry in this
626	   * task context.  Do not call rptun_initialize() here: the /dev/rptun/ap
627	   * instance is already registered and initialization is one-shot. */
628	
629	  ret = -EBUSY;
630	  for (attempt = 0; attempt < BK7258_AP_RPTUN_STOP_ATTEMPTS; attempt++)
631	    {
632	      ret = rptun_poweroff("ap");
633	      if (ret != -EBUSY)
634	        {
635	          break;
636	        }
637	
638	      nxsig_usleep(BK7258_AP_RPTUN_STOP_WAIT_USEC);
639	    }
640	
641	  if (ret == -EBUSY)
642	    {
643	      syslog(LOG_ERR,
644	             "[AP] RPTUN teardown remained busy after %u attempts\n",
645	             BK7258_AP_RPTUN_STOP_ATTEMPTS);
646	    }
647	
648	  if (ret < 0 && ret != -ENODEV)
649	    {
650	      syslog(LOG_ERR, "[AP] RPTUN teardown failed: %d\n", ret);
651	      goto out;
652	    }
653	
654	  ret = rptun_boot("ap");
655	  if (ret < 0)
656	    {
657	      syslog(LOG_ERR, "[AP] RPTUN restart failed: %d\n", ret);
658	    }
659	
660	out:
661	  g_ap_recovering = false;
662	  return ret;
663	}
