704	static int bk7258_ap_monitor(int argc, char *argv[])
705	{
706	  struct bk7258_ap_boot_record_s record;
707	  uint32_t last_heartbeat = 0;
708	  uint32_t last_stage = UINT32_MAX;
709	  uint32_t last_dbg = 0;
710	  unsigned int invalid_samples = 0;
711	  unsigned int stagnant_samples = 0;
712	  bool invalid_reported = false;
713	  bool stalled_reported = false;
714	  bool heartbeat_seen = false;
715	  unsigned int token_samples = 0;
716	
717	  (void)argc;
718	  (void)argv;
719	
720	  for (; ; )
721	    {
722	      /* An AP that died while dumping must not mute the CP for good. */
723	
724	      if (!bk7258_ap_uart_token_held())
725	        {
726	          token_samples = 0;
727	        }
728	      else if (++token_samples >= BK7258_AP_UART_TOKEN_SAMPLES)
729	        {
730	          bk7258_ap_uart_token_release();
731	          syslog(LOG_ERR, "[AP] UART0 panic token held %u s; reclaimed\n",
732	                 token_samples);
733	          token_samples = 0;
734	        }
735	
736	      if (!bk7258_ap_record_read(&record) ||
737	          (record.boot_sequence != g_ap_boot_sequence &&
738	           !g_ap_recovering))
739	        {
740	          if (bk7258_ap_record_read(&record) &&
741	              record.boot_sequence != g_ap_boot_sequence &&
742	              record.stage == BK7258_AP_STAGE_SCHEDULER_RUNNING)
743	            {
744	              syslog(LOG_INFO,
745	                     "[AP] peer generation changed old=%u new=%u; rebuilding RPTUN\n",
746	                     (unsigned int)g_ap_boot_sequence,
747	                     (unsigned int)record.boot_sequence);
748	              (void)bk7258_ap_recover_transport();
749	              nxsig_usleep(1000 * 1000);
750	              continue;
751	            }
752	
753	          invalid_samples++;
754	          stagnant_samples = 0;
755	          if (invalid_samples >= BK7258_AP_STALL_SAMPLES && !invalid_reported)
756	            {
757	              syslog(LOG_ERR,
758	                     "[AP] no valid record for seq=%u\n",
759	                     (unsigned int)g_ap_boot_sequence);
760	              invalid_reported = true;
761	            }
762	
763	          nxsig_usleep(1000 * 1000);
764	          continue;
765	        }
766	
767	      invalid_samples = 0;
768	      invalid_reported = false;
769	
770	      {
771	        uint32_t dbg = bk7258_ap_dbg_read();
772	
773	        if (dbg != last_dbg)
774	          {
775	            syslog(LOG_INFO, "[AP] bootmark=0x%08x\n", dbg);
776	            last_dbg = dbg;
777	          }
778	      }
779	
780	      if (record.stage != last_stage)
781	        {
782	          if (record.stage == BK7258_AP_STAGE_FAULT &&
783	              (record.fault & UINT32_C(0xffff0000)) ==
784	              (BK7258_AP_FAULT_PANIC_BASE & UINT32_C(0xffff0000)))
785	            {
786	              /* The AP panic notifier encodes the assertion location:
787	               * high byte = a short hash of the filename, low byte = line
788	               * number. */
789	
790	              syslog(LOG_ERR,
791	                     "[AP] stage=fault seq=%u panic filehash=0x%02x line=%u\n",
792	                     (unsigned int)record.boot_sequence,
793	                     (unsigned int)((record.fault >> 8) & UINT32_C(0xff)),
794	                     (unsigned int)(record.fault & UINT32_C(0xff)));
795	              bk7258_ap_print_panic(record.boot_sequence);
796	            }
797	          else
798	            {
799	              syslog(record.stage == BK7258_AP_STAGE_FAULT ? LOG_ERR : LOG_INFO,
800	                     "[AP] stage=%s seq=%u fault=0x%08x\n",
801	                     bk7258_ap_stage_name(record.stage),
802	                     (unsigned int)record.boot_sequence,
803	                     (unsigned int)record.fault);
804	            }
805	
806	          last_stage = record.stage;
807	        }
808	
809	      if (record.stage == BK7258_AP_STAGE_SCHEDULER_RUNNING)
810	        {
811	          if (record.heartbeat != last_heartbeat)
812	            {
813	              stagnant_samples = 0;
814	              stalled_reported = false;
815	              last_heartbeat = record.heartbeat;
816	              heartbeat_seen = true;
817	            }
818	          else if (heartbeat_seen)
819	            {
820	              stagnant_samples++;
821	              if (stagnant_samples >= BK7258_AP_STALL_SAMPLES &&
822	                  !stalled_reported)
823	                {
824	                  syslog(LOG_ERR,
825	                         "[AP] stalled seq=%u heartbeat=%u samples=%u\n",
826	                         (unsigned int)record.boot_sequence,
827	                         (unsigned int)record.heartbeat,
828	                         stagnant_samples);
829	                  stalled_reported = true;
830	                }
831	            }
832	        }
833	
834	      nxsig_usleep(1000 * 1000);
835	    }
836	
837	  return 0;
838	}
839	
840	/* True once the AP released in this CP boot runs its scheduler.  SWAP
841	 * survives a watchdog reset, so the previous boot's RUNNING record must not
842	 * count: require the sequence board_start_cpu() prepared. */
843	
844	bool bk7258_ap_is_running(void)
845	{
846	  struct bk7258_ap_boot_record_s record;
847	
848	  return g_ap_started && bk7258_ap_record_read(&record) &&
849	         record.boot_sequence == g_ap_boot_sequence &&
850	         record.stage == BK7258_AP_STAGE_SCHEDULER_RUNNING &&
851	         record.heartbeat >= 2;
852	}
853	
854	int bk7258_ap_start_monitor(void)
855	{
856	  int ret;
857	
858	  ret = boardctl(BOARDIOC_START_CPU, 1);
859	  if (ret < 0)
860	    {
861	      syslog(LOG_ERR, "[AP] CPU1 release failed: %d errno=%d\n",
862	             ret, get_errno());
863	      return ret;
864	    }
865	
866	  syslog(LOG_INFO, "[AP] release seq=%u vector=0x%08x\n",
867	         (unsigned int)g_ap_boot_sequence,
868	         (unsigned int)BK7258_AP_XIP_VECTOR_BASE);
869	
870	  /* RPTUN restart reuses the long-lived CP monitor. Do not create a second
871	   * monitor thread when the generic RPTUN start path rebuilds a transport. */
872	
873	  if (g_ap_monitor_started)
874	    {
875	      return 0;
876	    }
877	
878	  ret = kthread_create("ap-monitor", BK7258_AP_MONITOR_PRIORITY,
879	                       BK7258_AP_MONITOR_STACK_SIZE,
880	                       bk7258_ap_monitor, NULL);
881	  if (ret < 0)
882	    {
883	      syslog(LOG_ERR, "[AP] monitor creation failed: %d\n", ret);
884	      nxmutex_lock(&g_ap_start_lock);
885	      (void)bk7258_ap_force_reset();
886	      g_ap_started = false;
887	      nxmutex_unlock(&g_ap_start_lock);
888	      return ret;
889	    }
890	
891	  return 0;
892	}
