28	#define BK7258_AP_STALL_SAMPLES          3
29	#define BK7258_AP_UART_TOKEN_SAMPLES     15 /* s an AP dump may hold UART0 */
30	#define BK7258_AP_POWER_STABILIZE_LOOPS  1000
31	#define BK7258_AP_POWER_WAIT_LOOPS       10000
32	#define BK7258_AP_RESET_WAIT_ATTEMPTS    50
33	#define BK7258_AP_RESET_WAIT_USEC        (10 * 1000)
34	#define BK7258_AP_RPTUN_STOP_ATTEMPTS    50
