37	/* HALT is deliberately NOT part of the verified lifecycle state.
38	 *
39	 * The authority's release sequence is reset_cpu1_core()
40	 * (cp/components/bk_startup/system_main.c:175-183), reached from
41	 * start_cpu1_core():
42	 *
43	 *   sys_drv_set_cpu1_pwr_dw(0);
44	 *   sys_drv_set_cpu1_rxevt_sel(1);
45	 *   sys_drv_set_cpu1_boot_address_offset(offset >> 8);
46	 *   sys_drv_set_cpu1_reset(start_flag);
47	 *
48	 * Four field writes, no halt among them and no read-back verification at all.
49	 * Upstream reaches that code with halt already asserted -- its own
50	 * pm_hardware_init() runs sys_hal_power_config_default(), which powers CPU1 OFF
51	 * by setting halt and pwr_dw (sys_hal.c:159-165) -- and CPU1 still starts.  So
52	 * a set halt bit is not a launch precondition on this part.
53	 *
54	 * Requiring it here made the release fail as soon as PM init moved to its
55	 * authority position in __start() (/tmp/0910-vela-11.log and the run after it):
56	 *
57	 *   before=00000018            HALT(bit3) | cpu1_speed(bit4)
58	 *   readback=00000038 expected=00000020 -> EIO
59	 *
60	 * pwr_dw clears and stays clear -- visible as before= dropping from 0x1a to
61	 * 0x18 once the CPU1 power vote was added above -- but halt does not, even
62	 * though sys_hal_module_power_ctrl()'s ON branch writes both fields in adjacent
63	 * instructions (verified in the disassembly at 0x201203c and 0x2012044).  The
64	 * hardware appears to hold halt while the core is in reset; that is inference,
65	 * not something measured, but it is exactly the state upstream releases from
66	 * without complaint.
67	 *
68	 * This mask is the same set of bits minus HALT, so every other lifecycle field
69	 * stays verified. */
70	
71	#define BK7258_AP_CPU1_CTRL_LIFECYCLE_MASK \
72	  (BK7258_SYS_CPU1_RESET_RELEASE | BK7258_SYS_CPU1_POWER_DOWN | \
73	   BK7258_SYS_CPU1_RXEVT_SEL | BK7258_SYS_CPU1_OFFSET_MASK)
74	
75	static uint32_t g_ap_boot_sequence;
76	static mutex_t g_ap_start_lock = NXMUTEX_INITIALIZER;
77	static bool g_ap_started;
78	static bool g_ap_recovering;
79	static bool g_ap_monitor_started;
