150	static const char *bk7258_ap_stage_name(uint32_t stage)
151	{
152	  switch (stage)
153	    {
154	      case BK7258_AP_STAGE_CP_PREPARED:
155	        return "prepared";
156	      case BK7258_AP_STAGE_RESET_ENTERED:
157	        return "reset-entered";
158	      case BK7258_AP_STAGE_SCHEDULER_RUNNING:
159	        return "scheduler-running";
160	      case BK7258_AP_STAGE_FAULT:
161	        return "fault";
162	      default:
163	        return "unknown";
164	    }
165	}
166	
167	static int bk7258_ap_force_reset(void)
168	{
169	  irqstate_t flags;
170	  uint32_t control;
171	
172	  flags = up_irq_save();
173	  control = bk7258_ap_reg_read(BK7258_SYS_CPU1_CTRL);
174	  control &= ~BK7258_SYS_CPU1_RESET_RELEASE;
175	  bk7258_ap_reg_write(BK7258_SYS_CPU1_CTRL, control);
176	  bk7258_ap_lifecycle_barrier();
177	  if ((bk7258_ap_reg_read(BK7258_SYS_CPU1_CTRL) &
178	       BK7258_SYS_CPU1_RESET_RELEASE) != 0)
179	    {
180	      up_irq_restore(flags);
181	      return -EIO;
182	    }
183	
184	  up_irq_restore(flags);
185	  return 0;
186	}
