188	int bk7258_ap_reset_for_rptun(void)
189	{
190	  int ret;
191	
192	  ret = nxmutex_lock(&g_ap_start_lock);
193	  if (ret < 0)
194	    {
195	      return ret;
196	    }
197	
198	  ret = bk7258_ap_force_reset();
199	  if (ret >= 0)
200	    {
201	      g_ap_started = false;
202	    }
203	
204	  nxmutex_unlock(&g_ap_start_lock);
205	  return ret;
206	}
