665	/* Print the AP panic record.  The AP writes it once without and once with
666	 * its backtrace, so give the unwinder a moment before reading. */
667	
668	static void bk7258_ap_print_panic(uint32_t boot_sequence)
669	{
670	  struct bk7258_ap_panic_s panic;
671	  uint32_t i;
672	
673	  nxsig_usleep(200 * 1000);
674	
675	  /* The AP is still printing its own dump on UART0; output from here would
676	   * be dropped until it hands the token back. */
677	
678	  for (i = 0; i < BK7258_AP_UART_TOKEN_SAMPLES * 10 &&
679	              bk7258_ap_uart_token_held(); i++)
680	    {
681	      nxsig_usleep(100 * 1000);
682	    }
683	
684	  if (!bk7258_ap_panic_read(&panic, boot_sequence))
685	    {
686	      syslog(LOG_ERR, "[AP] panic record missing for seq=%u\n",
687	             (unsigned int)boot_sequence);
688	      return;
689	    }
690	
691	  syslog(LOG_ERR, "[AP] panic %s:%u task=%s msg=%s\n",
692	         panic.filename, (unsigned int)panic.linenum, panic.task,
693	         panic.msg);
694	  syslog(LOG_ERR, "[AP] panic pc=0x%08x lr=0x%08x sp=0x%08x\n",
695	         (unsigned int)panic.pc, (unsigned int)panic.lr,
696	         (unsigned int)panic.sp);
697	  for (i = 0; i < panic.nbt; i++)
698	    {
699	      syslog(LOG_ERR, "[AP] panic bt[%u]=0x%08x\n", (unsigned int)i,
700	             (unsigned int)panic.bt[i]);
701	    }
