2	 * chips/bk7258/bk7258_ap_boot.c
3	 ****************************************************************************/
4	
5	#include <nuttx/config.h>
6	
7	#include <assert.h>
8	#include <stddef.h>
9	#include <stdint.h>
10	
11	#include "include/bk7258_ap_boot.h"
12	#include "include/bk7258_memorymap.h"
13	
14	#define BK7258_AP_RECORD_WORDS \
15	  (sizeof(struct bk7258_ap_boot_record_s) / sizeof(uint32_t))
16	#define BK7258_AP_RECORD_READ_ATTEMPTS 3
17	#define BK7258_AP_GENERATION_MAGIC UINT32_C(0x4150474e) /* "APGN" */
18	#define BK7258_AP_GENERATION_SLOTS 2
19	
20	struct bk7258_ap_generation_s
21	{
22	  uint32_t magic;
23	  uint32_t sequence;
24	  uint32_t inverse;
25	  uint32_t checksum;
26	};
27	
28	static_assert(sizeof(struct bk7258_ap_boot_record_s) == 64,
29	              "BK7258 AP boot record ABI must remain 64 bytes");
30	static_assert(sizeof(struct bk7258_ap_boot_record_s) +
31	              sizeof(struct bk7258_ap_generation_s) *
32	                BK7258_AP_GENERATION_SLOTS <= BK7258_SWAP_SIZE,
33	              "BK7258 AP records exceed the locked SWAP region");
34	static_assert((BK7258_AP_SWAP_C2_WORD + 1) * sizeof(uint32_t) <=
35	                BK7258_SWAP_SIZE,
36	              "BK7258 AP CPU2 flag word exceeds the locked SWAP region");
37	
38	static_assert(BK7258_AP_PANIC_OFFSET >
39	                (BK7258_AP_SWAP_C2_WORD + 1) * sizeof(uint32_t),
40	              "BK7258 AP panic record overlaps the SWAP word map");
41	static_assert(BK7258_AP_SWAP_UART_WORD > BK7258_AP_SWAP_C2_WORD &&
42	              (BK7258_AP_SWAP_UART_WORD + 1) * sizeof(uint32_t) <=
43	                BK7258_AP_PANIC_OFFSET,
44	              "BK7258 AP UART token overlaps the SWAP word map");
45	static_assert(BK7258_AP_PANIC_OFFSET + sizeof(struct bk7258_ap_panic_s) <=
46	                BK7258_SWAP_SIZE,
47	              "BK7258 AP panic record exceeds the locked SWAP region");
48	
49	static volatile struct bk7258_ap_panic_s *const g_ap_panic =
50	  (volatile struct bk7258_ap_panic_s *)
51	    (BK7258_SWAP_BASE + BK7258_AP_PANIC_OFFSET);
52	
53	static volatile struct bk7258_ap_boot_record_s *const g_ap_record =
54	  (volatile struct bk7258_ap_boot_record_s *)BK7258_SWAP_BASE;
55	static volatile struct bk7258_ap_generation_s *const g_ap_generation =
56	  (volatile struct bk7258_ap_generation_s *)
57	    (BK7258_SWAP_BASE + sizeof(struct bk7258_ap_boot_record_s));
58	
59	static inline void bk7258_ap_barrier(void)
60	{
61	  __asm__ volatile ("dmb" : : : "memory");
62	}
63	
64	static uint32_t bk7258_ap_checksum(
65	  const struct bk7258_ap_boot_record_s *record)
66	{
67	  const uint32_t *words = (const uint32_t *)record;
68	  uint32_t checksum = UINT32_C(0x7258a5a5);
69	  size_t index;
70	
71	  for (index = 1; index < BK7258_AP_RECORD_WORDS - 1; index++)
72	    {
73	      checksum = (checksum << 5) | (checksum >> 27);
74	      checksum ^= words[index];
75	    }
76	
77	  return checksum;
78	}
79	
80	static uint32_t bk7258_ap_generation_checksum(uint32_t sequence)
81	{
82	  uint32_t rotated = (sequence << 13) | (sequence >> 19);
83	
84	  return BK7258_AP_GENERATION_MAGIC ^ sequence ^ rotated ^
85	         UINT32_C(0x7258474e);
86	}
87	
88	static bool bk7258_ap_generation_valid(
89	  const volatile struct bk7258_ap_generation_s *slot)
90	{
91	  uint32_t sequence = slot->sequence;
92	
93	  bk7258_ap_barrier();
94	  return slot->magic == BK7258_AP_GENERATION_MAGIC && sequence != 0 &&
95	         slot->inverse == ~sequence &&
96	         slot->checksum == bk7258_ap_generation_checksum(sequence);
97	}
98	
99	static uint32_t bk7258_ap_recover_sequence(void)
100	{
101	  uint32_t sequence = 0;
102	  unsigned int index;
103	
104	  bk7258_ap_barrier();
105	  for (index = 0; index < BK7258_AP_GENERATION_SLOTS; index++)
106	    {
107	      if (bk7258_ap_generation_valid(&g_ap_generation[index]) &&
108	          g_ap_generation[index].sequence > sequence)
109	        {
110	          sequence = g_ap_generation[index].sequence;
111	        }
112	    }
113	
114	  return sequence;
115	}
116	
117	static uint32_t bk7258_ap_next_sequence(void)
118	{
119	  volatile struct bk7258_ap_generation_s *slot;
120	  uint32_t sequence = bk7258_ap_recover_sequence();
121	  unsigned int index;
122	
123	  if (sequence == UINT32_MAX)
124	    {
125	      /* Define the 32-bit wrap explicitly. CP owns SWAP while CPU1 is held in
126	       * reset, so invalidate both old generations before restarting at one.
127	       * A reset between invalidations cannot revive a stale slot because each
128	       * magic store is an atomic 32-bit write. */
129	
130	      for (index = 0; index < BK7258_AP_GENERATION_SLOTS; index++)
131	        {
132	          g_ap_generation[index].magic = 0;
133	          bk7258_ap_barrier();
134	        }
135	
136	      sequence = 1;
137	    }
138	  else
139	    {
140	      sequence++;
141	    }
142	  slot = &g_ap_generation[sequence & 1];
143	
144	  /* Preserve the other valid slot until this one is fully committed. A reset
145	   * during any of the first three stores therefore still leaves one complete
146	   * previous generation available. */
147	
148	  slot->magic = 0;
149	  bk7258_ap_barrier();
150	  slot->sequence = sequence;
151	  slot->inverse = ~sequence;
152	  slot->checksum = bk7258_ap_generation_checksum(sequence);
153	  bk7258_ap_barrier();
154	  slot->magic = BK7258_AP_GENERATION_MAGIC;
155	  bk7258_ap_barrier();
156	  return sequence;
157	}
158	
159	static void bk7258_ap_write(struct bk7258_ap_boot_record_s *record)
160	{
161	  volatile uint32_t *destination = (volatile uint32_t *)g_ap_record;
162	  const uint32_t *source = (const uint32_t *)record;
163	  uint32_t commit = (g_ap_record->commit + 1) | 1;
164	  size_t index;
165	
166	  destination[0] = commit;
167	  bk7258_ap_barrier();
168	
169	  record->checksum = bk7258_ap_checksum(record);
170	  for (index = 1; index < BK7258_AP_RECORD_WORDS; index++)
171	    {
172	      destination[index] = source[index];
173	    }
174	
175	  bk7258_ap_barrier();
176	  destination[0] = commit + 1;
177	  bk7258_ap_barrier();
178	}
179	
180	bool bk7258_ap_record_read(struct bk7258_ap_boot_record_s *record)
181	{
182	  const volatile uint32_t *source = (const volatile uint32_t *)g_ap_record;
183	  uint32_t *destination = (uint32_t *)record;
184	  uint32_t first;
185	  uint32_t last;
186	  unsigned int attempt;
187	  size_t index;
188	
189	  for (attempt = 0; attempt < BK7258_AP_RECORD_READ_ATTEMPTS; attempt++)
190	    {
191	      first = source[0];
192	      if ((first & 1) != 0)
193	        {
194	          __asm__ volatile ("nop");
195	          continue;
196	        }
197	
198	      /* Acquire the payload after observing an even commit value. */
199	
200	      bk7258_ap_barrier();
201	
202	      for (index = 0; index < BK7258_AP_RECORD_WORDS; index++)
203	        {
204	          destination[index] = source[index];
205	        }
206	
207	      bk7258_ap_barrier();
208	      last = source[0];
209	      if (first != last || (last & 1) != 0)
210	        {
211	          continue;
212	        }
213	
214	      return record->magic == BK7258_AP_BOOT_MAGIC &&
215	             record->abi_version == BK7258_AP_BOOT_ABI_VERSION &&
216	             record->size == sizeof(*record) &&
217	             record->checksum == bk7258_ap_checksum(record);
218	    }
219	
220	  return false;
221	}
222	
223	uint32_t bk7258_ap_record_prepare(void)
224	{
225	  struct bk7258_ap_boot_record_s record = {0};
226	  volatile uint32_t *words = (volatile uint32_t *)g_ap_record;
227	
228	  words[BK7258_AP_SWAP_UART_WORD] = 0;
229	
230	  record.boot_sequence = bk7258_ap_next_sequence();
231	  record.magic = BK7258_AP_BOOT_MAGIC;
232	  record.abi_version = BK7258_AP_BOOT_ABI_VERSION;
233	  record.size = sizeof(record);
234	  record.stage = BK7258_AP_STAGE_CP_PREPARED;
235	  record.vector_base = BK7258_AP_XIP_VECTOR_BASE;
236	  record.build_id = BK7258_AP_BUILD_ID;
237	  bk7258_ap_write(&record);
238	  return record.boot_sequence;
239	}
240	
241	static bool bk7258_ap_current(struct bk7258_ap_boot_record_s *record)
242	{
243	  if (!bk7258_ap_record_read(record))
244	    {
245	      *record = (struct bk7258_ap_boot_record_s){0};
246	      record->magic = BK7258_AP_BOOT_MAGIC;
247	      record->abi_version = BK7258_AP_BOOT_ABI_VERSION;
248	      record->size = sizeof(*record);
249	      record->boot_sequence = bk7258_ap_recover_sequence();
250	      record->build_id = BK7258_AP_BUILD_ID;
251	      return false;
252	    }
253	
254	  return true;
255	}
256	
257	void bk7258_ap_record_mark_reset(uint32_t vector_base, uint32_t reset_pc)
258	{
259	  struct bk7258_ap_boot_record_s record;
260	
261	  bk7258_ap_current(&record);
262	  if (record.boot_sequence == 0)
263	    {
264	      return;
265	    }
266	
267	  /* A reset observed while the record still describes a running AP was
268	   * initiated by AP itself (or by hardware), rather than by CP's
269	   * board_start_cpu() transaction.  Allocate a new generation so CP can
270	   * distinguish an AP-only reboot from an ordinary stage transition without
271	   * depending on the RPMsg transport that is about to disappear.  CP writes
272	   * CP_PREPARED before releasing CPU1, so CP-managed resets retain the
273	   * sequence prepared by the owner. */
274	
275	  if (record.stage == BK7258_AP_STAGE_SCHEDULER_RUNNING)
276	    {
277	      record.boot_sequence = bk7258_ap_next_sequence();
278	      record.stage = BK7258_AP_STAGE_CP_PREPARED;
279	    }
280	
281	  record.stage = BK7258_AP_STAGE_RESET_ENTERED;
282	  record.heartbeat = 0;
283	  record.fault = 0;
284	  record.vector_base = vector_base;
285	  record.reset_pc = reset_pc;
286	  bk7258_ap_write(&record);
287	}
