290	{
291	  struct bk7258_ap_boot_record_s record;
292	
293	  bk7258_ap_current(&record);
294	  if (record.boot_sequence == 0)
295	    {
296	      return;
297	    }
298	  record.stage = BK7258_AP_STAGE_SCHEDULER_RUNNING;
299	  bk7258_ap_write(&record);
300	}
