392	void bk7258_ap_panic_write(struct bk7258_ap_panic_s *panic)
393	{
394	  volatile uint32_t *destination = (volatile uint32_t *)g_ap_panic;
395	  const uint32_t *source = (const uint32_t *)panic;
396	  struct bk7258_ap_boot_record_s record;
397	  size_t index;
398	
399	  bk7258_ap_current(&record);
400	  panic->boot_sequence = record.boot_sequence;
401	  panic->magic = BK7258_AP_PANIC_MAGIC;
402	
403	  destination[0] = 0;
404	  bk7258_ap_barrier();
405	  for (index = 1; index < sizeof(*panic) / sizeof(uint32_t); index++)
406	    {
407	      destination[index] = source[index];
408	    }
409	
410	  bk7258_ap_barrier();
411	  destination[0] = BK7258_AP_PANIC_MAGIC;
412	  bk7258_ap_barrier();
413	}
414	
415	bool bk7258_ap_panic_read(struct bk7258_ap_panic_s *panic,
416	                          uint32_t boot_sequence)
417	{
418	  const volatile uint32_t *source = (const volatile uint32_t *)g_ap_panic;
419	  uint32_t *destination = (uint32_t *)panic;
420	  size_t index;
421	
422	  bk7258_ap_barrier();
423	  for (index = 0; index < sizeof(*panic) / sizeof(uint32_t); index++)
424	    {
425	      destination[index] = source[index];
426	    }
427	
428	  bk7258_ap_barrier();
429	  if (source[0] != BK7258_AP_PANIC_MAGIC ||
430	      panic->magic != BK7258_AP_PANIC_MAGIC ||
431	      panic->boot_sequence != boot_sequence)
432	    {
433	      return false;
434	    }
435	
436	  panic->filename[sizeof(panic->filename) - 1] = '\0';
437	  panic->task[sizeof(panic->task) - 1] = '\0';
438	  panic->msg[sizeof(panic->msg) - 1] = '\0';
439	  if (panic->nbt > BK7258_AP_PANIC_NBT)
440	    {
441	      panic->nbt = BK7258_AP_PANIC_NBT;
442	    }
443	
444	  return true;
445	}
