41	/* This record occupies the first 64 bytes of the locked 2 KiB SWAP region.
42	 * CP is the only writer before CPU1 reset release; AP is the only writer after
43	 * release.  commit is a seqlock: odd means an update is in progress, even
44	 * means readers may verify the checksum and accept a stable snapshot.
45	 */
46	
47	struct bk7258_ap_boot_record_s
48	{
49	  uint32_t commit;
50	  uint32_t magic;
51	  uint32_t abi_version;
52	  uint32_t size;
53	  uint32_t boot_sequence;
54	  uint32_t stage;
55	  uint32_t heartbeat;
56	  uint32_t fault;
57	  uint32_t vector_base;
58	  uint32_t reset_pc;
59	  uint32_t build_id;
60	  uint32_t reserved[4];
61	  uint32_t checksum;
62	};
