360	/* ── Voice failure cooldown — prevent error-message cascade ──── */
361	
362	static volatile bool s_voice_cooldown;
363	static time_t s_voice_cooldown_until;
364	
365	/**
366	 * Reads messages from the outbound queue and dispatches them to the
367	 * appropriate channel (FeiShu, WebSocket, CLI, etc.).
368	 */
369	static void* outbound_dispatch_task(void* arg)
370	{
371	    (void)arg;
372	    syslog(LOG_INFO, "[%s] Outbound dispatch started\n", TAG);
373	
374	    while (!g_shutdown_requested) {
375	        agent_msg_t msg;
376	        if (message_bus_pop_outbound(&msg, 1000) != OK)
377	            continue;
378	        msg.channel[sizeof(msg.channel) - 1] = '\0';
379	        msg.chat_id[sizeof(msg.chat_id) - 1] = '\0';
380	
381	        if (!msg.content) {
382	            syslog(LOG_WARNING, "[%s] Skip outbound message with NULL content\n", TAG);
383	            continue;
384	        }
385	
386	        syslog(LOG_INFO, "[%s] Dispatching response → %s:%s\n", TAG, msg.channel, msg.chat_id);
387	
388	        /* Let registered taps intercept before normal dispatch */
389	        if (mbus_tap_try_deliver(&msg)) {
390	            free(msg.content);
391	            continue;
392	        }
393	
394	        if (strcmp(msg.channel, AGENT_CHAN_FEISHU) == 0) {
395	            bool delivered = false;
396	#ifdef CONFIG_AI_AGENT_FEISHU
397	            const char* app_id = feishu_get_app_id();
398	            if (app_id && app_id[0] != '\0') {
399	                feishu_send_message(msg.chat_id, msg.content);
400	                delivered = true;
401	            }
402	#endif
403	#ifdef CONFIG_AI_AGENT_NODE
404	            if (!delivered) {
405	                delivered = node_client_send_chat_message(
406	                    msg.channel, msg.chat_id, msg.content) == OK;
407	            }
408	#endif
409	            if (!delivered) {
410	                syslog(LOG_WARNING,
411	                    "[%s] Feishu message dropped: no local config "
412	                    "and no gateway\n",
413	                    TAG);
414	            }
415	        } else if (strcmp(msg.channel, AGENT_CHAN_WEBSOCKET) == 0) {
416	            ws_server_send(msg.chat_id, msg.content);
417	#ifdef CONFIG_AI_AGENT_MQTT
418	        } else if (strcmp(msg.channel, AGENT_CHAN_MQTT) == 0) {
419	            mqtt_channel_send(msg.chat_id, msg.content);
420	#endif
421	        } else if (strcmp(msg.channel, AGENT_CHAN_VOICE) == 0) {
422	            /* Check voice cooldown — skip voice dispatch if a recent
423	             * speak call failed, to prevent error-message cascade. */
424	            if (s_voice_cooldown && time(NULL) < s_voice_cooldown_until) {
425	                syslog(LOG_WARNING,
426	                    "[%s] voice cooldown active, dropping message\n", TAG);
427	            } else {
428	                s_voice_cooldown = false;
429	                int vret = voice_channel_speak(msg.content);
430	                if (vret != 0) {
431	                    syslog(LOG_ERR, "[%s] voice_channel_speak failed: %d\n", TAG, vret);
432	                    s_voice_cooldown = true;
433	                    s_voice_cooldown_until = time(NULL) + 5;
434	#if defined(CONFIG_AI_AGENT_LVGL_UI) || defined(CONFIG_AI_AGENT_UI_RPMSG)
435	                    /* TTS failed — drive the pet to ERROR (red+shake) so the
436	                     * user sees the failure on screen, not just a silent skip.
437	                     * 5 = PET_STATE_ERROR (pet_status_view.h). */
438	                    (void)lvgl_ui_channel_set_pet_state(5);
439	#endif
440	                }
441	            }
442	#if defined(CONFIG_AI_AGENT_LVGL_UI) || defined(CONFIG_AI_AGENT_UI_RPMSG)
443	        } else if (strcmp(msg.channel, AGENT_CHAN_LVGL_UI) == 0) {
444	            int uret = lvgl_ui_channel_send(msg.content);
445	            if (uret != 0) {
446	                syslog(LOG_ERR, "[%s] lvgl_ui_channel_send failed: %d\n", TAG, uret);
447	            }
448	#endif
449	#ifdef CONFIG_AI_AGENT_NOTIFY_SERVICE
450	        } else if (strcmp(msg.channel, AGENT_CHAN_LVGL_NOTIFY) == 0) {
451	            /* Transient toast notice. The toast itself is already popped
452	             * by the notify service (which knows the exact title + color);
453	             * this branch only mirrors to the CLI for debug visibility and
454	             * does NOT enter the chat history. */
455	            pthread_mutex_lock(&g_stdout_lock);
456	            printf("\n[Notify]: %s\nvela> ", msg.content);
457	            fflush(stdout);
458	            pthread_mutex_unlock(&g_stdout_lock);
459	#endif
460	#ifdef CONFIG_AI_AGENT_WEIXIN
461	        } else if (strcmp(msg.channel, AGENT_CHAN_WEIXIN) == 0) {
462	            /* chat_id format: "from_user_id|context_token" */
463	            char uid[64] = "";
464	            const char* ctx = "";
465	            char* sep = strchr(msg.chat_id, '|');
466	            if (sep) {
467	                size_t ulen = (size_t)(sep - msg.chat_id);
468	                if (ulen >= sizeof(uid))
469	                    ulen = sizeof(uid) - 1;
470	                memcpy(uid, msg.chat_id, ulen);
471	                uid[ulen] = '\0';
472	                ctx = sep + 1;
473	            } else {
474	                strncpy(uid, msg.chat_id, sizeof(uid) - 1);
475	            }
476	            weixin_channel_send(uid, ctx, msg.content);
477	#endif
478	        } else if (strcmp(msg.channel, AGENT_CHAN_SYSTEM) == 0) {
479	            syslog(LOG_INFO, "[%s] System message [%s]: %.128s\n", TAG, msg.chat_id, msg.content);
480	#ifdef CONFIG_FEATURE_SYSTEM_VELACLAW
481	        } else if (strcmp(msg.channel, AGENT_CHAN_QUICKAPP) == 0) {
482	            quickapp_mq_dispatch(msg.chat_id, msg.content);
483	#endif
484	        } else if (strcmp(msg.channel, "cli") == 0) {
485	            pthread_mutex_lock(&g_stdout_lock);
486	            printf("\n[Agent]: %s\nvela> ", msg.content);
487	            fflush(stdout);
488	            pthread_mutex_unlock(&g_stdout_lock);
489	            /* One printer only.  This syslog line used to carry the full
490	             * reply a second time, and on a board where syslog shares the
491	             * console the user saw the answer twice.  Log the shape of it
492	             * for the record, not the text.
493	             */
494	
495	            syslog(LOG_INFO, "[agent] reply %u bytes\n",
496	                (unsigned)strlen(msg.content));
497	#if defined(CONFIG_AI_AGENT_LVGL_UI) || defined(CONFIG_AI_AGENT_UI_RPMSG)
498	            /* Mirror CLI replies to the LVGL UI so that `ask` responses
499	             * (which come in on the "cli" channel) also render as chat
500	             * cards on screen, not only as terminal text.  send() shows
501	             * the chat screen on first call, so the UI comes up
502	             * automatically when the first reply arrives. */
503	            lvgl_ui_channel_send(msg.content);
504	#endif
505	        } else {
506	            syslog(LOG_WARNING, "[%s] Unknown channel: %s\n", TAG, msg.channel);
507	        }
508	
509	        free(msg.content);
510	    }
511	
512	    syslog(LOG_INFO, "[%s] Outbound dispatch exiting\n", TAG);
513	    return NULL;
514	}
