360	 * owns the display + event loop; this channel only creates widgets.
361	 * On qemu-arm64-v8a-ap there is no such process, so the channel must
362	 * bring up LVGL itself: lv_init() + lv_nuttx_init(/dev/fb0) + a
363	 * lv_timer_handler() loop thread.  s_lv_owned tracks whether WE did
364	 * the init so stop() can deinit symmetrically. */
365	static bool s_lv_owned = false;
366	static pthread_t s_lv_loop_tid;
367	static pthread_t s_lv_wd_tid;
368	static volatile bool s_lv_loop_running = false;
369	static lv_nuttx_result_t s_lv_result;
370	
371	/* LVGL log sink (see the registration in lv_loop_thread). */
372	static void lvgl_log_cb(lv_log_level_t level, const char* buf)
373	{
374	    (void)level;
375	    syslog(LOG_INFO, "[lvgl] %s", buf);
376	}
377	
378	/* Frame counter polled by the UI watchdog.  Bumped by the LVGL loop. */
379	static volatile uint32_t s_lv_frames;
380	
381	/* Watchdog ticks.  Printed by the LVGL thread's heartbeat as well as by the
382	 * watchdog itself: if the watchdog's own console write is ever lost, a
383	 * rising tick count in the heartbeat still proves the thread is scheduled. */
384	static volatile uint32_t s_wd_ticks;
385	
386	/* How far the watchdog thread got.  1 = entered, 2 = priority set,
387	 * 3 = raw console write returned, 4 = syslog returned.  Frozen at 1 means
388	 * the thread never ran at all; frozen at 2/3 means it blocks in console
389	 * output.  Read from the heartbeat, so it needs no output of its own. */
390	static volatile int s_wd_stage;
391	static volatile int s_wd_prio = -1;
392	static volatile int s_wd_setrc = -2;
393	
394	/* UI watchdog (BUG-20261021-01).  Two very different failures look the
395	 * same in the log: the LVGL thread wedging inside a widget call, and the
396	 * whole AP dying.  The watchdog runs above the LVGL thread's priority, so
397	 * if it keeps printing while the frame counter is frozen, the scheduler
398	 * and the console are alive and the LVGL thread is the stuck one; if it
399	 * goes silent too, the AP or the console path itself is gone. */
400	static void* ui_watchdog_thread(void* arg)
401	{
402	    struct sched_param got;
403	    char bfr[192];
404	    int n;
405	    uint32_t last = 0;
406	    int stall = 0;
407	
408	    (void)arg;
409	
410	    /* First statement on purpose: a store, no syscall, no console.  If the
411	     * heartbeat reports stage 1 forever, this thread never got scheduled at
412	     * all — which is a different bug from one that blocks in console output
413	     * (stage 2/3). */
414	    s_wd_stage = 1;
415	
416	    /* Priority is set at pthread_create() time via the attribute (see
417	     * lv_loop_thread below), NOT here.  A self sched_setparam(0) to the
418	     * highest priority hangs on this config (observed stage 1 forever),
419	     * so read the effective priority back instead of raising it. */
420	    memset(&got, 0, sizeof(got));
421	    int grc = sched_getparam(0, &got);
422	    s_wd_prio = (grc == 0) ? got.sched_priority : -1;
423	    s_wd_setrc = 0;
424	    s_wd_stage = 2;
425	
426	    /* Unconditional beacon through BOTH channels: as long as these keep
427	     * coming, the scheduler and the serial output are alive and any silence
428	     * elsewhere is a stuck thread, not a dead AP.  Sending it twice keeps
429	     * the answer readable even if one of the two paths is wedged.  The
430	     * priority read-back says whether the thread really runs at 20. */
431	    n = snprintf(bfr, sizeof(bfr),
432	                 "\r\n[lvgl_ui] wd up setrc=%d prio=%d getrc=%d\r\n",
433	                 s_wd_setrc, s_wd_prio, grc);
434	    if (n > 0)
435	      {
436	        ssize_t ign = write(1, bfr, (size_t)n);
437	        (void)ign;
438	      }
439	    s_wd_stage = 3;
440	
441	    syslog(LOG_INFO, "[%s] wd up setrc=%d prio=%d getrc=%d\n",
442	           TAG, s_wd_setrc, s_wd_prio, grc);
443	    s_wd_stage = 4;
444	
445	    while (s_lv_loop_running)
446	      {
447	        uint32_t cur;
448	
449	        usleep(5000 * 1000);
450	        if (!s_lv_loop_running)
451	          {
452	            break;
453	          }
454	
455	        s_wd_ticks++;
456	
457	        cur = s_lv_frames;
458	        if (cur == last)
459	          {
460	            stall += 5;
461	          }
462	        else
463	          {
464	            last = cur;
465	            stall = 0;
466	          }
467	
468	        /* `tr` is the last probe step the UI thread reached: a frozen frame
469	         * count plus a frozen tr names the widget call that never returned.
470	         * `lvl` is the patched-LVGL layout progress: outer passes / object
471	         * visits / refr_size calls, and the class being worked on.  While the
472	         * frames are frozen, growing lvl = spinning inside layout; static lvl
473	         * = blocked inside one call. */
474	        n = snprintf(bfr, sizeof(bfr),
475	                     "\r\n[lvgl_ui] wd frames %lu stall %d tr %d lvl %lu/%lu/%lu %s\r\n",
476	                     (unsigned long)cur, stall, s_ui_trace_step,
477	                     (unsigned long)lv_dbg_layout_outer,
478	                     (unsigned long)lv_dbg_layout_calls,
479	                     (unsigned long)lv_dbg_refr_calls,
480	                     lv_dbg_class ? lv_dbg_class : "-");
481	        if (n > 0)
482	          {
483	            ssize_t ign = write(1, bfr, (size_t)n);
484	            (void)ign;
485	          }
486	
487	        if (stall > 0)
488	          {
489	            syslog(LOG_WARNING,
490	                   "[%s] wd: LVGL stalled %ds (frames=%lu tr=%d)\n",
491	                   TAG, stall, (unsigned long)cur, s_ui_trace_step);
492	          }
493	      }
494	
495	    return NULL;
496	}
497	
498	static void* lv_loop_thread(void* arg)
499	{
500	    struct sched_param sp;
501	    uint32_t frames = 0;
502	
503	    (void)arg;
504	
505	    /* LV_USE_LOG is on but LV_LOG_PRINTF is off, so every LVGL log line —
506	     * including "Asserted at expression: ... (Out of memory)" — was being
507	     * discarded.  Route them to syslog so an assert is visible before
508	     * lv_assert_handler() takes the system down. */
509	    lv_log_register_print_cb(lvgl_log_cb);
510	
511	    /* The loop thread was created with the default pthread priority
512	     * (inherited), so TLS / LLM dispatch / TTS work preempts it.  A frame
513	     * that is preempted mid-flush holds lvgl_ui_lock() for that whole
514	     * time, and every cross-thread LVGL caller (agent reply path, pet
515	     * state, PTT) blocks behind it.  Run at the UI priority instead. */
516	    sp.sched_priority = AGENT_LVGL_UI_PRIO;
517	    int prc = sched_setparam(0, &sp);
518	    syslog(LOG_INFO, "[%s] LVGL loop prio -> %d (rc=%d)\n",
519	           TAG, AGENT_LVGL_UI_PRIO, prc);
520	
521	    /* Stall detector — see ui_watchdog_thread().  Give it an explicit 8 KB
522	     * stack: CONFIG_PTHREAD_STACK_DEFAULT is 2048 here, which is marginal for
523	     * one snprintf, and the previous run's watchdog never printed a byte while
524	     * every other thread kept logging — a too-small stack is the likeliest
525	     * reason.  The creation result is logged so a silent watchdog can no
526	     * longer be confused with a wedged scheduler. */
527	    {
528	      pthread_attr_t wattr;
529	      int crc = -1;
530	
531	      if (pthread_attr_init(&wattr) == 0)
532	        {
533	          struct sched_param wsp;
534	
535	          (void)pthread_attr_setstacksize(&wattr, 8192);
536	          wsp.sched_priority = 20;   /* above the LVGL loop (45) */
537	          (void)pthread_attr_setschedparam(&wattr, &wsp);
538	          (void)pthread_attr_setschedpolicy(&wattr, SCHED_FIFO);
539	          (void)pthread_attr_setinheritsched(&wattr, PTHREAD_EXPLICIT_SCHED);
540	          crc = pthread_create(&s_lv_wd_tid, &wattr, ui_watchdog_thread, NULL);
541	          (void)pthread_attr_destroy(&wattr);
542	        }
543	
544	      syslog(LOG_INFO, "[%s] watchdog create rc=%d\n", TAG, crc);
545	    }
546	
547	    while (s_lv_loop_running) {
548	        uint32_t idle;
549	        struct timespec t0;
550	        struct timespec t1;
551	        long ms;
552	
553	        /* Serialize with cross-thread lv_async_call()/lv_timer_create()
554	         * users.  CONFIG_LV_USE_OS=0 means LVGL does no locking itself. */
555	        clock_gettime(CLOCK_MONOTONIC, &t0);
556	        lvgl_ui_lock();
557	        idle = lv_timer_handler();
558	        lvgl_ui_unlock();
559	        s_lv_frames++;
560	        clock_gettime(CLOCK_MONOTONIC, &t1);
561	
562	        ms = (t1.tv_sec - t0.tv_sec) * 1000
563	           + (t1.tv_nsec - t0.tv_nsec) / 1000000;
564	
565	        /* One slow frame is the first symptom of a wedged render/flush;
566	         * log it while the board is still talking. */
567	        if (ms >= 300)
568	          {
569	            syslog(LOG_WARNING, "[%s] handler %ldms idle=%u\n",
570	                   TAG, ms, (unsigned)idle);
571	          }
572	
573	        /* Heartbeat: ~every 5 s at the normal cadence.  Silence after a
574	         * hang means the LVGL thread itself stopped, not just the caller. */
575	        if (++frames % 20 == 0)
576	          {
577	            char hb[192];
578	            int hn;
579	
580	#if defined(CONFIG_STACK_COLORATION)
581	            /* Stack high-water for this thread: if the reply-card build
582	             * overflows the 64 KB LVGL stack, the log simply stops with no
583	             * message, so surface the headroom while the board still talks. */
584	            struct stackinfo_s si = {0};
585	            size_t used = 0;
586	
587	            if (nxsched_get_stackinfo(0, &si) == 0 && si.adj_stack_size > 0)
588	              {
589	                used = up_check_tcbstack(nxsched_self(), si.adj_stack_size);
590	              }
591	
592	            hn = snprintf(hb, sizeof(hb),
593	                          "\r\n[lvgl_ui] hb frames stack %lu %lu wd %lu st %d pr %d "
594	                          "lvl %lu/%lu/%lu\r\n",
595	                          (unsigned long)frames, (unsigned long)used,
596	                          (unsigned long)s_wd_ticks, s_wd_stage, s_wd_prio,
597	                          (unsigned long)lv_dbg_layout_outer,
598	                          (unsigned long)lv_dbg_layout_calls,
599	                          (unsigned long)lv_dbg_refr_calls);
600	#else
601	            hn = snprintf(hb, sizeof(hb),
602	                          "\r\n[lvgl_ui] hb frames %lu 0 wd %lu st %d pr %d\r\n",
603	                          (unsigned long)frames, (unsigned long)s_wd_ticks,
604	                          s_wd_stage, s_wd_prio);
605	#endif
606	            if (hn > 0)
607	              {
608	                ssize_t ign = write(1, hb, (size_t)hn);
609	                (void)ign;
610	              }
611	          }
612	
613	        if (idle == 0)
614	            idle = 1;
615	        usleep(idle * 1000);
616	    }
617	    return NULL;
618	}
