115	static void bk7258_rptun_enable_shared_sram(void)
116	{
117	  volatile uint32_t *power_wakeup =
118	    (volatile uint32_t *)BK7258_SYS_POWER_WAKEUP;
119	  uint32_t value = *power_wakeup;
120	
121	  /* RPMSG_SHM spans the shared SRAM bank below CP RAM. Keep shared-SRAM
122	   * clock gating disabled while either core can touch the resource table,
123	   * vrings or RPMsg buffers. SWAP heartbeat alone did not exercise this bank.
124	   */
125	
126	  *power_wakeup = value | BK7258_SYS_SHARE_MEM_CLKGATING_DISABLE;
127	  __asm__ volatile ("dsb\n\tisb" : : : "memory");
128	  (void)*power_wakeup;
129	}
