141	static struct resource_table *
142	bk7258_rptun_get_resource(struct rptun_dev_s *dev)
143	{
144	  struct bk7258_rptun_dev_s *priv =
145	    container_of(dev, struct bk7258_rptun_dev_s, rptun);
146	  struct rptun_rsc_s *rsc = &priv->shmem->rsc;
147	  uintptr_t carveout_base;
148	  size_t carveout_size;
149	
150	  if (priv->master)
151	    {
152	      rsc->rsc_tbl_hdr.ver = 1;
153	      rsc->rsc_tbl_hdr.num = 2;
154	      rsc->rsc_tbl_hdr.reserved[0] = 0;
155	      rsc->rsc_tbl_hdr.reserved[1] = 0;
156	      rsc->offset[0] = offsetof(struct rptun_rsc_s, rpmsg_vdev);
157	      rsc->offset[1] = offsetof(struct rptun_rsc_s, carveout);
158	
159	      rsc->rpmsg_vdev.type = RSC_VDEV;
160	      rsc->rpmsg_vdev.id = VIRTIO_ID_RPMSG;
161	      rsc->rpmsg_vdev.notifyid = RSC_NOTIFY_ID_ANY;
162	      rsc->rpmsg_vdev.dfeatures =
163	        (UINT32_C(1) << VIRTIO_RPMSG_F_NS) |
164	        (UINT32_C(1) << VIRTIO_RPMSG_F_ACK) |
165	        (UINT32_C(1) << VIRTIO_RPMSG_F_BUFSZ) |
166	        (UINT32_C(1) << VIRTIO_RPMSG_F_CPUNAME);
167	      /* The device side (AP) derives its feature set from
168	       * virtio_get_features() == dfeatures & gfeatures
169	       * (rproc_virtio_get_features).  Leaving gfeatures at 0 -- as
170	       * this dynamically-built table always did -- empties that AND
171	       * on the device side, so rpmsg_virtio never registers the NS
172	       * endpoint (support_ns = false) and every NS announcement the
173	       * AP sends via rpmsg_create_ept() is silently dropped in
174	       * rpmsg.c.  The RPMsg UART console survives because its
175	       * endpoints do not depend on NS announcements; the rpmsg-net
176	       * driver, whose peer must bind on the "rpmsg-net-rpmsg0"
177	       * announcement, does not.  Declare the device-side acceptance
178	       * of the same feature bits so the AND keeps them on both
179	       * sides.  The CP (driver) side is unaffected: its
180	       * negotiate_features() writes its own acceptance into gfeatures
181	       * before setting DRIVER_OK, and the AP's create loop retries
182	       * on -EAGAIN until that status appears, so it never reads the
183	       * table before the negotiation has landed. */
184	      rsc->rpmsg_vdev.gfeatures =
185	        (UINT32_C(1) << VIRTIO_RPMSG_F_NS) |
186	        (UINT32_C(1) << VIRTIO_RPMSG_F_ACK) |
187	        (UINT32_C(1) << VIRTIO_RPMSG_F_BUFSZ) |
188	        (UINT32_C(1) << VIRTIO_RPMSG_F_CPUNAME);
189	      rsc->rpmsg_vdev.config_len = sizeof(struct fw_rsc_config);
190	      rsc->rpmsg_vdev.status = 0;
191	      rsc->rpmsg_vdev.num_of_vrings = BK7258_RPTUN_VRINGS;
192	      /* The resource-table host is the VirtIO driver. RPTUN XORs this field
193	       * with its local master flag, yielding driver on CP and device on AP. */
194	
195	      rsc->rpmsg_vdev.reserved[0] = VIRTIO_DEV_DRIVER;
196	      rsc->rpmsg_vdev.reserved[1] = 0;
197	
198	      rsc->rpmsg_vring0.da = FW_RSC_U32_ADDR_ANY;
199	      rsc->rpmsg_vring0.align = BK7258_RPTUN_VRING_ALIGN;
200	      rsc->rpmsg_vring0.num = BK7258_RPTUN_VRING_NUM;
201	      rsc->rpmsg_vring0.notifyid = RSC_NOTIFY_ID_ANY;
202	      rsc->rpmsg_vring0.reserved = 0;
203	      rsc->rpmsg_vring1.da = FW_RSC_U32_ADDR_ANY;
204	      rsc->rpmsg_vring1.align = BK7258_RPTUN_VRING_ALIGN;
205	      rsc->rpmsg_vring1.num = BK7258_RPTUN_VRING_NUM;
206	      rsc->rpmsg_vring1.notifyid = RSC_NOTIFY_ID_ANY;
207	      rsc->rpmsg_vring1.reserved = 0;
208	
209	      memset(&rsc->config, 0, sizeof(rsc->config));
210	      rsc->config.h2r_buf_size = BK7258_RPTUN_BUFFER_SIZE;
211	      rsc->config.r2h_buf_size = BK7258_RPTUN_BUFFER_SIZE;
212	      strlcpy((char *)rsc->config.host_cpuname, "cp",
213	              sizeof(rsc->config.host_cpuname));
214	      strlcpy((char *)rsc->config.remote_cpuname, "ap",
215	              sizeof(rsc->config.remote_cpuname));
216	
217	      carveout_base = ALIGN_UP((uintptr_t)rsc + sizeof(*rsc),
218	                               BK7258_RPTUN_VRING_ALIGN);
219	      carveout_size = CONFIG_BK7258_RPMSG_SHM_ADDR +
220	                      CONFIG_BK7258_RPMSG_SHM_SIZE - carveout_base;
221	      rsc->carveout.type = RSC_CARVEOUT;
222	      rsc->carveout.da = carveout_base;
223	      rsc->carveout.pa = FW_RSC_U32_ADDR_ANY;
224	      rsc->carveout.len = carveout_size;
225	      rsc->carveout.flags = 0;
226	      rsc->carveout.reserved = 0;
227	      strlcpy((char *)rsc->carveout.name, "rpmsg_shm",
228	              sizeof(rsc->carveout.name));
229	
230	      bk7258_rptun_barrier();
231	      priv->shmem->base = CONFIG_BK7258_RPMSG_SHM_ADDR;
232	      bk7258_rptun_barrier();
233	    }
234	  else
235	    {
236	      while (priv->shmem->base != CONFIG_BK7258_RPMSG_SHM_ADDR)
237	        {
238	          nxsig_usleep(100);
239	        }
240	
241	      bk7258_rptun_barrier();
242	    }
243	
244	  return &rsc->rsc_tbl_hdr;
245	}
