289	static int bk7258_rptun_reset(struct rptun_dev_s *dev,
290	                              unsigned long value)
291	{
292	  (void)dev;
293	
294	  if (value == BOARDIOC_SOFTRESETCAUSE_PANIC)
295	    {
296	#ifdef CONFIG_BK7258_RPTUN_PANIC_PEER
297	      /* -ENOTSUP selects the NuttX default: post PANIC in the resource
298	       * table status, kick the peer and wait for it to answer, so the peer
299	       * panics and dumps its own state too.  Resetting CPU1 here would wipe
300	       * the AP before it could print anything. */
301	
302	      return -ENOTSUP;
303	#else
304	      /* Leave the peer running. */
305	
306	      return 0;
307	#endif
308	    }
309	
310	#ifdef CONFIG_BK7258_COMPONENT_CP
311	  /* CP owns the CPU1 lifecycle.  A successful callback means the remote AP
312	   * has been asserted; CP's own board_reset() will reset CPU0 immediately
313	   * afterwards and its normal bring-up will release AP again. */
314	  return bk7258_ap_reset_for_rptun();
315	#else
316	  /* A reboot from the AP is a whole-chip reboot.  -ENOTSUP selects the
317	   * NuttX default path: flag the reason in the resource table status and
318	   * kick the CP, whose rptun_check_peer_status() runs
319	   * boardctl(BOARDIOC_RESET, reason), i.e. the AON WDT chip reset.  The CP
320	   * owns the CPU1 lifecycle; an AP-local SYSRESETREQ raced the CP monitor's
321	   * generation check and asserted in rpmsg_virtio_buf_held_dec_test(). */
322	  return -ENOTSUP;
323	#endif
324	}
