380	static int bk7258_rptun_register_callback(struct rptun_dev_s *dev,
381	                                          rptun_callback_t callback,
382	                                          void *arg)
383	{
384	  struct bk7258_rptun_dev_s *priv =
385	    container_of(dev, struct bk7258_rptun_dev_s, rptun);
386	  irqstate_t flags;
387	
388	  flags = enter_critical_section();
389	  priv->callback = callback;
390	  priv->callback_arg = arg;
391	  leave_critical_section(flags);
392	
393	  if (callback != NULL)
394	    {
395	      /* Match the established NuttX nRF53/STM32 RPTUN pattern: scan once
396	       * after callback registration to cover peer writes that predate local
397	       * IRQ setup.  All subsequent notifications are hardware-driven.
398	       */
399	
400	      callback(arg, RPTUN_NOTIFY_ALL);
401	    }
402	
403	  return 0;
404	}
405	
406	static void bk7258_rptun_mbox_callback(uint8_t src_cpu, uint32_t data0,
407	                                       uint32_t data1, void *arg)
408	{
409	  struct bk7258_rptun_dev_s *priv = arg;
410	  unsigned int local = priv->master ? 0 : 1;
411	  uint8_t peer = priv->master ? 1 : 0;
412	
413	  (void)data0;
414	  if (src_cpu != peer || data1 != BK7258_MBOX_RPTUN_MAGIC)
415	    {
416	      return;
417	    }
418	
419	  /* Re-arm the direction before scanning.  A concurrent sender either
420	   * coalesced before this clear (and is covered by this scan), or observes
421	   * zero and emits a new hardware doorbell.
422	   */
423	
424	  priv->shmem->mbox_pending[local] = 0;
425	  bk7258_rptun_barrier();
426	  if (priv->callback != NULL)
427	    {
428	      priv->callback(priv->callback_arg, RPTUN_NOTIFY_ALL);
429	    }
430	}
