432	int bk7258_rptun_initialize(void)
433	{
434	  unsigned int local = g_bk7258_rptun.master ? 0 : 1;
435	  int ret;
436	
437	  bk7258_rptun_enable_shared_sram();
438	
439	  if (g_bk7258_rptun.master)
440	    {
441	      memset(g_bk7258_rptun.shmem, 0, CONFIG_BK7258_RPMSG_SHM_SIZE);
442	      bk7258_rptun_barrier();
443	    }
444	
445	  ret = bk7258_mbox_attach(bk7258_rptun_mbox_callback,
446	                           &g_bk7258_rptun);
447	  if (ret < 0)
448	    {
449	      return ret;
450	    }
451	
452	  ret = bk7258_mbox_init(g_bk7258_rptun.master);
453	  if (ret < 0)
454	    {
455	      return ret;
456	    }
457	
458	  /* Mailbox init has discarded entries left by an earlier boot.  Re-arm the
459	   * matching shared latch only after that drain, so a restarted core cannot
460	   * leave its peer permanently coalescing against stale state.
461	   */
462	
463	  g_bk7258_rptun.shmem->mbox_pending[local] = 0;
464	  bk7258_rptun_barrier();
465	
466	  ret = rptun_initialize(&g_bk7258_rptun.rptun);
467	  if (ret < 0)
468	    {
469	      return ret;
470	    }
471	
472	  ret = rptun_boot(bk7258_rptun_get_cpuname(&g_bk7258_rptun.rptun));
473	  if (ret < 0)
474	    {
475	      return ret;
476	    }
477	
478	  return 0;
479	}
