569	                                          FAR void *data, size_t len_,
570	                                          uint32_t src, FAR void *priv_)
571	{
572	  struct iovec iov[CONFIG_NET_USRSOCK_RPMSG_SERVER_NIOVEC];
573	  FAR struct usrsock_request_recvfrom_s *req = data;
574	  FAR struct usrsock_message_datareq_ack_s *ack;
575	  FAR struct usrsock_rpmsg_s *priv = priv_;
576	  socklen_t outaddrlen = req->max_addrlen;
577	  socklen_t inaddrlen = req->max_addrlen;
578	  size_t buflen = req->max_buflen;
579	  size_t totlen = 0;
580	  ssize_t ret = -EBADF;
581	  uint32_t len = buflen;
582	  uint16_t events = 0;
583	  uint8_t i = 0;
584	  int retr;
585	
586	  ack = rpmsg_get_tx_payload_buffer(ept, &len, true);
587	  if (sizeof(*ack) + inaddrlen + buflen < len)
588	    {
589	      len = sizeof(*ack) + inaddrlen + buflen;
590	    }
591	
592	  memset(iov, 0, sizeof(iov));
593	  if (req->usockid >= 0 &&
594	      req->usockid < CONFIG_NET_USRSOCK_RPMSG_SERVER_NSOCKS)
595	    {
596	      ret = psock_recvfrom(&priv->socks[req->usockid],
597	              (FAR void *)(ack + 1) + inaddrlen,
598	              len - sizeof(*ack) - inaddrlen,
599	              req->flags,
600	              outaddrlen ? (FAR struct sockaddr *)(ack + 1) : NULL,
601	              outaddrlen ? &outaddrlen : NULL);
602	      totlen = ret;
603	      if (ret > 0 && (priv->socks[req->usockid].s_type & SOCK_TYPE_MASK) ==
604	                      SOCK_STREAM)
605	        {
606	          FAR struct socket_conn_s *conn = priv->socks[req->usockid].s_conn;
607	          if (outaddrlen < inaddrlen)
608	            {
609	              memcpy((FAR void *)(ack + 1) + outaddrlen,
610	                     (FAR void *)(ack + 1) + inaddrlen, ret);
611	            }
612	
613	          /* Hold conn_lock to combine get_tx_payload and recvfrom together.
614	           * Otherwise we may keep holding tx buffer when waiting conn_lock
615	           * in recvfrom, which may block rpmsg and may cause dead lock if
616	           * another thread tries to get tx buffer with conn_lock held.
617	           */
618	
619	          nxrmutex_lock(&conn->s_lock);
620	          while (totlen < buflen &&
621	                 i < CONFIG_NET_USRSOCK_RPMSG_SERVER_NIOVEC)
622	            {
623	              uint32_t offset = sizeof(struct usrsock_message_frag_ack_s);
624	
625	              if (!usrsock_rpmsg_available(&priv->socks[req->usockid],
626	                                           FIONREAD))
627	                {
628	                  break;
629	                }
630	
631	              iov[i].iov_base = rpmsg_get_tx_payload_buffer(ept,
632	                                                            &len,
633	                                                            false);
634	              if (!iov[i].iov_base)
635	                {
636	                  break;
637	                }
638	
639	              DEBUGASSERT(len > offset);
640	              if (buflen - totlen < len - offset)
641	                {
642	                  len = buflen - totlen + offset;
643	                }
644	
645	              /* Should never wait */
646	
647	              iov[i].iov_len =
648	                psock_recvfrom(&priv->socks[req->usockid],
649	                    (FAR char *)iov[i].iov_base + offset,
650	                    len - offset,
651	                    req->flags | MSG_DONTWAIT,
652	                    NULL, NULL);
653	              if ((ssize_t)iov[i].iov_len > 0)
654	                {
655	                  totlen += iov[i].iov_len;
656	                  if (iov[i].iov_len < len - offset)
657	                    {
658	                      break;
659	                    }
660	                }
661	              else
662	                {
663	                  iov[i].iov_len = 0;
664	                  break;
665	                }
666	
667	              i++;
668	            }
669	
670	          if (usrsock_rpmsg_available(&priv->socks[req->usockid], FIONREAD))
671	            {
672	              events |= USRSOCK_EVENT_RECVFROM_AVAIL;
673	            }
674	
675	          nxrmutex_unlock(&conn->s_lock);
676	        }
677	    }
678	
679	  retr = usrsock_rpmsg_send_data_ack(ept,
680	                                     ack, events, req->head.xid,
681	                                     totlen, inaddrlen, outaddrlen,
682	                                     ret);
683	  for (i = 0; i < CONFIG_NET_USRSOCK_RPMSG_SERVER_NIOVEC; i++)
684	    {
685	      if (!iov[i].iov_base)
686	        {
687	          break;
688	        }
689	
690	      if (!iov[i].iov_len || retr <= 0)
691	        {
692	          rpmsg_release_tx_buffer(ept, iov[i].iov_base);
693	          iov[i].iov_base = NULL;
694	          continue;
695	        }
696	
697	      usrsock_rpmsg_send_frag_ack(ept,
698	            (FAR struct usrsock_message_frag_ack_s *)iov[i].iov_base,
699	            events, req->head.xid, totlen, iov[i].iov_len);
700	    }
701	
702	  if (retr >= 0 && (ret > 0 || ret == -EAGAIN) && events == 0)
703	    {
704	      usrsock_rpmsg_poll_setup(&priv->pfds[req->usockid],
705	                               priv->pfds[req->usockid].events | POLLIN);
706	    }
707	
708	  return retr;
709	}
