423	static int usrsock_rpmsg_sendto_handler(FAR struct rpmsg_endpoint *ept,
424	                                        FAR void *data, size_t len,
425	                                        uint32_t src, FAR void *priv_)
426	{
427	  FAR struct usrsock_request_sendto_s *req;
428	  FAR struct usrsock_rpmsg_ept_s *uept =
429	    (FAR struct usrsock_rpmsg_ept_s *)ept;
430	  FAR struct usrsock_rpmsg_s *priv = priv_;
431	  uint16_t events = 0;
432	  ssize_t ret = -EBADF;
433	  int retr;
434	  int i;
435	
436	  if (uept->remain > 0)
437	    {
438	      size_t hlen;
439	      struct msghdr msg =
440	      {
441	      };
442	
443	      uept->remain -= len;
444	
445	      if (!uept->iov[0].iov_base)
446	        {
447	          /* Maybe error occurred previously, skip processing. */
448	
449	          return 0;
450	        }
451	
452	      req = uept->iov[0].iov_base;
453	      hlen = sizeof(*req) + req->addrlen;
454	
455	      for (i = 0; i < CONFIG_NET_USRSOCK_RPMSG_SERVER_NIOVEC; i++)
456	        {
457	          if (!uept->iov[i].iov_base)
458	            {
459	              uept->iov[i].iov_base = data;
460	              uept->iov[i].iov_len = len;
461	              rpmsg_hold_rx_buffer(ept, data);
462	              break;
463	            }
464	        }
465	
466	      /* Partial packet ? continue to fetch */
467	
468	      if (uept->remain > 0)
469	        {
470	          /* We've used the last I/O vector, cannot continue. */
471	
472	          if (i == CONFIG_NET_USRSOCK_RPMSG_SERVER_NIOVEC - 1)
473	            {
474	              nerr("ERROR: Request %d too large!\n", req->usockid);
475	              ret = -ENOMEM;
476	              goto out;
477	            }
478	
479	          return 0;
480	        }
481	      else if (uept->remain < 0)
482	        {
483	          ret = -EINVAL;
484	          goto out;
485	        }
486	
487	      /* Skip the sendto header from I/O vector */
488	
489	      uept->iov[0].iov_base = (FAR char *)uept->iov[0].iov_base + hlen;
490	      uept->iov[0].iov_len -= hlen;
491	
492	      msg.msg_name = req->addrlen ? (FAR void *)(req + 1) : NULL;
493	      msg.msg_namelen = req->addrlen;
494	      msg.msg_iov = uept->iov;
495	      msg.msg_iovlen = i + 1;
496	
497	      ret = psock_sendmsg(&priv->socks[req->usockid], &msg, req->flags);
498	
499	      /* Recover the I/O vector */
500	
501	      uept->iov[0].iov_base = (FAR char *)uept->iov[0].iov_base - hlen;
502	      uept->iov[0].iov_len += hlen;
503	    }
504	  else
505	    {
506	      req = data;
507	
508	      if (req->usockid >= 0 &&
509	          req->usockid < CONFIG_NET_USRSOCK_RPMSG_SERVER_NSOCKS)
510	        {
511	          uept->remain = sizeof(*req) + req->addrlen + req->buflen - len;
512	          if (uept->remain > 0)
513	            {
514	#if CONFIG_NET_USRSOCK_RPMSG_SERVER_NIOVEC >= 2
515	              uept->iov[0].iov_base = data;
516	              uept->iov[0].iov_len = len;
517	
518	              rpmsg_hold_rx_buffer(ept, data);
519	              return 0;
520	#else
521	              ret = -ENOMEM;
522	#endif
523	            }
524	          else
525	            {
526	              ret = psock_sendto(&priv->socks[req->usockid],
527	                  (FAR const void *)(req + 1) + req->addrlen, req->buflen,
528	                  req->flags,
529	                  req->addrlen ?
530	                        (FAR const struct sockaddr *)(req + 1) : NULL,
531	                  req->addrlen);
532	            }
533	        }
534	    }
535	
536	out:
537	  if (ret > 0 &&
538	      usrsock_rpmsg_available(&priv->socks[req->usockid], FIONSPACE))
539	    {
540	      events |= USRSOCK_EVENT_SENDTO_READY;
541	    }
542	
543	  retr = usrsock_rpmsg_send_ack(ept, events, req->head.xid, ret);
544	  if (retr >= 0 && (ret > 0 || ret == -EAGAIN) && events == 0)
545	    {
546	      usrsock_rpmsg_poll_setup(&priv->pfds[req->usockid],
547	                               priv->pfds[req->usockid].events | POLLOUT);
548	    }
549	
550	  if (uept->iov[0].iov_base)
551	    {
552	      for (i = 0; i < CONFIG_NET_USRSOCK_RPMSG_SERVER_NIOVEC; i++)
553	        {
554	          if (uept->iov[i].iov_base == NULL)
555	            {
556	              break;
557	            }
558	
559	          rpmsg_release_rx_buffer(ept, uept->iov[i].iov_base);
560	          uept->iov[i].iov_base = NULL;
561	          uept->iov[i].iov_len = 0;
562	        }
563	    }
564	
565	  return retr;
566	}
