200	int usrsock_request(FAR struct iovec *iov, unsigned int iovcnt)
201	{
202	  FAR struct usrsock_rpmsg_s *priv = &g_usrsock_rpmsg;
203	  size_t pos = 0;
204	  int ret = 0;
205	
206	  nxsem_get_value(&priv->wait, &ret);
207	  if (ret <= 0)
208	    {
209	      usrsock_sem_timedwait(&priv->wait, false, UINT_MAX);
210	      nxsem_post(&priv->wait);
211	    }
212	
213	  for (; ; )
214	    {
215	      FAR void *buf;
216	      uint32_t len;
217	      bool done;
218	
219	      buf = rpmsg_get_tx_payload_buffer(&priv->ept, &len, true);
220	      if (buf == NULL)
221	        {
222	          ret = -ENOMEM;
223	          break;
224	        }
225	
226	      ret = usrsock_iovec_get(buf, len, iov, iovcnt, pos, &done);
227	      if (ret < 0)
228	        {
229	          break;
230	        }
231	
232	      pos += ret;
233	      ret = rpmsg_send_nocopy(&priv->ept, buf, ret);
234	      if (ret < 0)
235	        {
236	          rpmsg_release_tx_buffer(&priv->ept, buf);
237	          break;
238	        }
239	
240	      if (done)
241	        {
242	          ret = OK;
243	          break;
244	        }
245	    }
246	
247	  return ret;
248	}
