static int rpmsg_is_address_set(unsigned long *bitmap, int size, int addr)
{
	int ret = RPMSG_ERR_PARAM;

	addr -= RPMSG_RESERVED_ADDRESSES;
	if (addr >= 0 && addr < size)
		ret = metal_bitmap_is_bit_set(bitmap, addr);

	return ret;
}

/**
 * @internal
 *
 * @brief Marks the address as consumed.
 *
 * @param bitmap	Bit map for addresses
 * @param size		Size of bitmap
 * @param addr		Address to free
 *
 * @return 0 on success, otherwise error code
 */
static int rpmsg_set_address(unsigned long *bitmap, int size, int addr)
{
	int ret = RPMSG_ERR_PARAM;

	addr -= RPMSG_RESERVED_ADDRESSES;
	if (addr >= 0 && addr < size) {
		metal_bitmap_set_bit(bitmap, addr);
		ret = RPMSG_SUCCESS;
	}

	return ret;
}

void rpmsg_ept_incref(struct rpmsg_endpoint *ept)
{
	if (ept) {
		metal_mutex_acquire(&ept->rdev->lock);
		ept->refcnt++;
		metal_mutex_release(&ept->rdev->lock);
	}
}

void rpmsg_ept_decref(struct rpmsg_endpoint *ept)
{
	if (ept) {
		metal_mutex_acquire(&ept->rdev->lock);
		ept->refcnt--;
		if (!ept->refcnt) {
			metal_mutex_release(&ept->rdev->lock);
			if (ept->release_cb)
				ept->release_cb(ept);
			else
				ept->rdev = NULL;
		} else {
			metal_mutex_release(&ept->rdev->lock);
		}
	}
}

