97	#ifdef CONFIG_SERIAL_TXDMA
98	void uart_xmitchars_dma(FAR uart_dev_t *dev)
99	{
100	  FAR struct uart_dmaxfer_s *xfer = &dev->dmatx;
101	
102	  if (dev->xmit.head == dev->xmit.tail)
103	    {
104	      /* No data to transfer. */
105	
106	      return;
107	    }
108	
109	  if (dev->xmit.tail < dev->xmit.head)
110	    {
111	      xfer->buffer  = &dev->xmit.buffer[dev->xmit.tail];
112	      xfer->length  = dev->xmit.head - dev->xmit.tail;
113	      xfer->nbuffer = NULL;
114	      xfer->nlength = 0;
115	    }
116	  else
117	    {
118	      xfer->buffer  = &dev->xmit.buffer[dev->xmit.tail];
119	      xfer->length  = dev->xmit.size - dev->xmit.tail;
120	      xfer->nbuffer = dev->xmit.buffer;
121	      xfer->nlength = dev->xmit.head;
122	    }
123	
124	  uart_dmasend(dev);
125	}
