128	/****************************************************************************
129	 * Name: uart_xmitchars_done
130	 *
131	 * Description:
132	 *   Perform operations necessary at the complete of DMA including adjusting
133	 *   the TX circular buffer indices and waking up of any threads that may
134	 *   have been waiting for space to become available in the TX circular
135	 *   buffer.
136	 *
137	 ****************************************************************************/
138	
139	#ifdef CONFIG_SERIAL_TXDMA
140	void uart_xmitchars_done(FAR uart_dev_t *dev)
141	{
142	  FAR struct uart_dmaxfer_s *xfer = &dev->dmatx;
143	  size_t nbytes = xfer->nbytes;
144	  struct uart_buffer_s *txbuf = &dev->xmit;
145	
146	  /* Skip the update if the tail position change which mean
147	   * someone reset (e.g. TCOFLUSH) the xmit buffer during DMA.
148	   */
149	
150	  if (xfer->buffer == &txbuf->buffer[txbuf->tail])
151	    {
152	      /* Move tail for nbytes. */
153	
154	      txbuf->tail  = (txbuf->tail + nbytes) % txbuf->size;
155	    }
156	
157	  /* Reset xmit buffer. */
158	
159	  xfer->nbytes = 0;
160	  xfer->length = xfer->nlength = 0;
161	
162	  /* If any bytes were removed from the buffer, inform any waiters there
163	   * there is space available.
164	   */
165	
166	  if (nbytes)
167	    {
168	      uart_datasent(dev);
169	    }
170	}
171	#endif
