184	static void uart_rpmsg_dmasend(FAR struct uart_dev_s *dev)
185	{
186	  FAR struct uart_rpmsg_priv_s *priv = dev->priv;
187	  FAR struct uart_dmaxfer_s *xfer = &dev->dmatx;
188	  FAR struct uart_rpmsg_write_s *msg;
189	  size_t len = xfer->length + xfer->nlength;
190	  uint32_t space;
191	
192	  /* BUG-20261021-01: this console shares its AP->CP RPMSG TX pool (4 x 2048B)
193	   * with the usrsock LLM traffic on the same RPTUN link.  A blocking get here
194	   * (wait=true) is effectively unbounded: rpmsg_virtio_notify_wait() maps
195	   * -ETIMEDOUT back to success, so the OpenAMP wait loop never decrements its
196	   * tick count and never returns NULL.  During an ask the pool is exhausted,
197	   * and every thread that prints -- the LVGL thread holding lvgl_ui_lock()
198	   * inside lv_timer_handler(), the agent loop blocked behind that lock, and
199	   * the watchdog blocked on its own write(1) -- wedges behind this call.
200	   * Fetch non-blocking instead: under contention the DMA attempt is dropped
201	   * (dmatx.length = 0 leaves the tail in place, so uart_xmitchars_dma() simply
202	   * retries it later) and the caller never blocks.  A lossy console beats a
203	   * dead AP. */
204	  msg = rpmsg_get_tx_payload_buffer(&priv->ept, &space, false);
205	  if (!msg)
206	    {
207	      dev->dmatx.length = 0;
208	      return;
209	    }
210	
211	  memset(msg, 0, sizeof(*msg));
212	
213	  space = space - sizeof(*msg);
214	
215	  if (len > space)
216	    {
217	      len = space;
218	    }
219	
220	  if (len > xfer->length)
221	    {
222	      memcpy(msg->data, xfer->buffer, xfer->length);
223	      memcpy(msg->data + xfer->length, xfer->nbuffer, len - xfer->length);
224	    }
225	  else
226	    {
227	      memcpy(msg->data, xfer->buffer, len);
228	    }
229	
230	  msg->count          = len;
231	  msg->header.command = UART_RPMSG_TTY_WRITE;
232	  msg->header.result  = -ENXIO;
233	  msg->header.cookie  = (uintptr_t)dev;
234	
235	  if (rpmsg_send_nocopy(&priv->ept, msg, sizeof(*msg) + len) < 0)
236	    {
237	      rpmsg_release_tx_buffer(&priv->ept, msg);
238	    }
239	}
