241	static void uart_rpmsg_dmareceive(FAR struct uart_dev_s *dev)
242	{
243	  FAR struct uart_rpmsg_priv_s *priv = dev->priv;
244	  FAR struct uart_dmaxfer_s *xfer = &dev->dmarx;
245	  FAR struct uart_rpmsg_write_s *msg = priv->recv_data;
246	  uint32_t len = msg->count;
247	  size_t space = xfer->length + xfer->nlength;
248	
249	  if (len > space)
250	    {
251	      len = space;
252	    }
253	
254	  if (len > xfer->length)
255	    {
256	      memcpy(xfer->buffer, msg->data, xfer->length);
257	      memcpy(xfer->nbuffer, msg->data + xfer->length, len - xfer->length);
258	    }
259	  else
260	    {
261	      memcpy(xfer->buffer, msg->data, len);
262	    }
263	
264	  xfer->nbytes = len;
265	  uart_recvchars_done(dev);
266	
267	  msg->header.result = len;
268	
269	  if (len != msg->count)
270	    {
271	      uart_rpmsg_rxflowcontrol(dev, 0, true);
272	    }
273	}
