378	static int uart_rpmsg_ept_cb(FAR struct rpmsg_endpoint *ept, FAR void *data,
379	                             size_t len, uint32_t src, FAR void *priv_)
380	{
381	  FAR struct uart_dev_s *dev = priv_;
382	  FAR struct uart_rpmsg_priv_s *priv = dev->priv;
383	  FAR struct uart_rpmsg_header_s *header = data;
384	  FAR struct uart_rpmsg_write_s *msg = data;
385	
386	  if (header->response)
387	    {
388	      /* Get write-cmd response, this tell how many data have sent */
389	
390	      nxmutex_lock(&priv->lock);
391	
392	      dev->dmatx.nbytes = header->result;
393	      if (header->result < 0)
394	        {
395	          dev->dmatx.nbytes = 0;
396	        }
397	
398	      uart_xmitchars_done(dev);
399	
400	      nxmutex_unlock(&priv->lock);
401	
402	      /* If have sent some data succeed, then continue send */
403	
404	      if (msg->count == header->result)
405	        {
406	          uart_rpmsg_dmatxavail(dev);
407	        }
408	    }
409	  else if (header->command == UART_RPMSG_TTY_WRITE)
410	    {
411	      irqstate_t flags;
412	
413	      /* Get write-cmd, there are some data, we need receive them */
414	
415	      flags = uart_spinlock(dev, true);
416	      priv->recv_data = data;
417	      uart_recvchars_dma(dev);
418	      priv->recv_data = NULL;
419	      uart_spinunlock(dev, true, flags);
420	
421	      header->response = 1;
422	      rpmsg_send(ept, msg, sizeof(*msg));
423	    }
424	  else if (header->command == UART_RPMSG_TTY_WAKEUP)
425	    {
426	      /* Remote core have space, then wakeup current core, continue send */
427	
428	      uart_rpmsg_dmatxavail(dev);
429	    }
430	
431	  return 0;
432	}
